NAMES[COMMON_DEPLOYED.syncTrigger.toLowerCase()] = 'SyncTrigger';
NAMES[COMMON_DEPLOYED.creReceiver.toLowerCase()] = 'CREReceiver';
NAMES[COMMON_DEPLOYED.pool.toLowerCase()] = 'OraclePool';
NAMES[COMMON_DEPLOYED.retiredSyncTrigger.toLowerCase()] = 'retired SyncTrigger';

// ── Minimal ABI plumbing ─────────────────────────────────────────────────────
const SEL = {
  owner: '0x8da5cb5b', getForwarder: '0xa0042526', getExpectedAuthor: '0x3397cf67',
  getOraclePool: '0x37d86246', getLastExecution: '0x7acd7f48', getDelay: '0xcebc9a82',
  getAmounts: '0x3d370b4e', getMaxFees: '0x77c46f80', shouldSyncAmount: '0x755b53a3',
  canSync: '0x269d5486', hasRole: '0x91d14854', balanceOf: '0x70a08231', isCallAllowed: '0x797c8d69',
  isOwnerLinked: '0x0987294c', getWorkflowListByOwner: '0x8c42ffc5', failedMessageHash: '0x34219403',
};
const pad = a => a.toLowerCase().replace('0x', '').padStart(64, '0');
const padU = n => BigInt(n).toString(16).padStart(64, '0');

// Minimal reader for the one dynamic return shape this page needs — getWorkflowListByOwner's
// (bytes32,address,uint64,uint8,string,string,string,string,bytes,string)[]. Deliberately not a
// general ABI library: it decodes this layout and returns null on anything it does not recognise,
// which lands on the same "unreadable → crit" path as the one-line decoders above.
const LAYOUT_WORKFLOW = ['b32', 'addr', 'u', 'u', 'str', 'str', 'str', 'str', 'hex', 'str'];
const utf8 = h => new TextDecoder().decode(Uint8Array.from(h.match(/../g) ?? [], p => parseInt(p, 16)));
function decodeTupleArray(hex, layout) {
  const b = (hex || '').replace(/^0x/, '');
  if (b.length < 64 || b.length % 64) return null;
  const words = b.length / 64;
  const w = i => b.slice(i * 64, i * 64 + 64);
  const u = i => BigInt('0x' + w(i));
  const jump = (base, slot) => {                 // relative offset at `slot`, resolved against `base`
    const off = Number(u(slot));
    if (off % 32) throw new Error('unaligned');
    const at = base + off / 32;
    if (at < 0 || at >= words) throw new Error('out of range');
    return at;
  };
  try {
    const arr = jump(0, 0);                      // head word 0 → the array
    const n = Number(u(arr));
    const elems = arr + 1;                       // element offsets are relative to just past the length
    if (n < 0 || elems + n > words) return null;
    return Array.from({ length: n }, (_, e) => {
      const t = jump(elems, elems + e);          // start of this tuple
      return layout.map((kind, s) => {
        const slot = t + s;
        if (slot >= words) throw new Error('short');
        if (kind === 'b32') return '0x' + w(slot);
        if (kind === 'addr') return '0x' + w(slot).slice(24);
        if (kind === 'u') return u(slot);
        const d = jump(t, slot);                 // dynamic member: offset relative to the tuple start
        const len = Number(u(d));
        const raw = b.slice((d + 1) * 64, (d + 1) * 64 + len * 2);
        if (raw.length < len * 2) throw new Error('short');
        return kind === 'hex' ? '0x' + raw : utf8(raw);
      });
    });
  } catch { return null; }
}
const call = (to, data) => ({ method: 'eth_call', params: [{ to, data }, 'latest'] });
const bal = a => ({ method: 'eth_getBalance', params: [a, 'latest'] });
const decAddr = h => h && h.length >= 66 ? '0x' + h.slice(-40) : null;
const decBool = h => h ? BigInt(h) !== 0n : null;
const decU = h => h ? BigInt(h) : null;

const rpcQueues = new Map();
const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
async function rpcFetch(url, init) {
  const request = async () => {
    let res;
    for (let attempt = 0; attempt < 3; attempt++) {
      res = await fetch(url, init);
      if (res.status !== 429) {
        if (url.includes('base.gateway.tenderly.co')) await wait(1000);
        return res;
      }
      await wait(500 * 2 ** attempt);
    }
    return res;
  };
  if (!url.includes('base.gateway.tenderly.co')) return request();
  const queued = (rpcQueues.get(url) ?? Promise.resolve()).then(request, request);
  rpcQueues.set(url, queued.then(() => undefined, () => undefined));
  return queued;
}

// Chunked so a batch-limited endpoint still works: free tiers commonly cap a batch (mainnet.optimism.io
// at 10) and answer an oversized one with a single error OBJECT instead of the per-call array, which
// used to surface as a bare "out.map is not a function". A lane reads ~20 calls, so this is 2 requests
// against the default endpoints and the ceiling stays below every cap seen in the wild.
const RPC_BATCH_MAX = 10;

async function rpcBatchChunk(url, calls, idBase) {
  const body = calls.map((c, i) => ({ jsonrpc: '2.0', id: idBase + i, ...c }));
  const res = await rpcFetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const out = await res.json();
  // A batch request answered with a single object is a whole-batch rejection (rate limit, batch-size
  // cap, auth). Report what it said — never let it fall through as a shape error.
  if (!Array.isArray(out)) throw new Error(out?.error?.message || 'endpoint rejected the batch request');
  const byId = new Map(out.map(r => [r.id, r]));
  return calls.map((_, i) => byId.get(idBase + i)?.result ?? null); // per-call revert → null
}

async function rpcBatch(url, calls) {
  const chunks = [];
  for (let i = 0; i < calls.length; i += RPC_BATCH_MAX) chunks.push(i);
  const parts = await Promise.all(chunks.map(i =>
    rpcBatchChunk(url, calls.slice(i, i + RPC_BATCH_MAX), i)));
  return parts.flat();
}

async function rpcBatchChunks(url, calls, size = 5) {
  const results = [];
  for (let i = 0; i < calls.length; i += size) results.push(...await rpcBatch(url, calls.slice(i, i + size)));
  return results;
}

async function rpcRequest(url, method, params) {
  const res = await rpcFetch(url, { method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }) });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const out = await res.json();
  if (out.error || out.result == null) throw new Error(out.error?.message || 'invalid RPC response');
  return out.result;
}

// ── Formatting ───────────────────────────────────────────────────────────────
const fmtEth = (wei, dp = 4) => wei == null ? '—' : (Number(wei) / 1e18).toLocaleString('en-US', { maximumFractionDigits: dp });
const short = a => a ? a.slice(0, 6) + '…' + a.slice(-4) : '—';
const who = a => a ? (NAMES[a.toLowerCase()] || short(a)) : '—';
function ago(ts) {
  if (ts == null) return '—';
  let s = Math.max(0, Math.floor(Date.now() / 1000) - Number(ts));
  const d = Math.floor(s / 86400); s %= 86400;
  const h = Math.floor(s / 3600); const m = Math.floor(s % 3600 / 60);
  return (d ? d + 'd ' : '') + (h ? h + 'h ' : '') + (d ? '' : m + 'm ') + 'ago';
}
const worst = levels => levels.includes('crit') ? 'crit' : levels.includes('warn') ? 'warn' : 'ok';
const chip = (level, main, sub) =>
  `<span class="chip ${level}"><div class="m">${level === 'ok' ? '✓ ' : level === 'warn' ? '⚠ ' : level === 'crit' ? '✕ ' : ''}${main}</div>${sub ? `<div class="s">${sub}</div>` : ''}</span>`;
const alink = (net, a, text) => `<a href="${net.explorer}/address/${a}" target="_blank" title="${a}">${text ?? short(a)}&thinsp;↗</a>`;
const refreshingViews = new Set();
const REFRESH_ICON = `<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M13.4 5.4A5.8 5.8 0 1 0 13 11"/><path d="M13.4 2.7v2.7h-2.7"/></svg>`;
const viewRefresh = (view, label) => {
  const loading = refreshingViews.has(view);
  return `<button class="view-refresh${loading ? ' loading' : ''}" data-refresh-view="${view}"
    title="Refresh ${label}" aria-label="Refresh ${label}"${loading ? ' disabled' : ''}>${REFRESH_ICON}</button>`;
};
function updateViewRefresh(view) {
  const button = document.querySelector(`[data-refresh-view="${view}"]`);
  if (!button) return;
  const loading = refreshingViews.has(view);
  button.classList.toggle('loading', loading);
  button.disabled = loading;
  if (view === 'activity') updateActivityUpd();
}

function ownerCheck(actual, target) {
  if (!actual) return ['crit', 'unreadable'];
  const a = actual.toLowerCase();
  if (target.toLowerCase() !== a) return ['crit', holder(actual)];
  return ['ok', holder(actual)];
}

// ── Data ─────────────────────────────────────────────────────────────────────
async function laneData(L) {
  const q = [
    call(L.sender, SEL.getOraclePool),                                   // 0
    call(L.sender, SEL.hasRole + pad(ADMIN_ROLE) + pad(L.gov)),          // 1
    call(L.sender, SEL.hasRole + pad(SYNC_ROLE) + pad(L.syncTrigger)),   // 2
    call(L.sender, SEL.hasRole + pad(SYNC_ROLE) + pad(L.retiredSyncTrigger)), // 3
    call(L.sender, SEL.hasRole + pad(SYNC_ROLE) + pad(L.oldAutomation)), // 4
    call(L.proxyAdmin, SEL.owner),                                       // 5
    call(L.syncTrigger, SEL.owner),                                      // 6
    call(L.syncTrigger, SEL.getForwarder),                               // 7
    call(L.syncTrigger, SEL.getLastExecution),                           // 8
    call(L.syncTrigger, SEL.getDelay),                                   // 9
    call(L.syncTrigger, SEL.getAmounts),                                 // 10
    call(L.syncTrigger, SEL.getMaxFees),                                 // 11
    call(L.syncTrigger, SEL.shouldSyncAmount),                           // 12
    call(L.syncTrigger, SEL.canSync),                                    // 13
    call(L.creReceiver, SEL.owner),                                      // 14
    call(L.creReceiver, SEL.getForwarder),                               // 15
    call(L.creReceiver, SEL.getExpectedAuthor),                          // 16
    call(L.creReceiver, SEL.isCallAllowed + pad(L.syncTrigger) + TRIGGER_SYNC_SEL.replace('0x', '').padEnd(64, '0')), // 17
    call(L.pool, SEL.owner),                                             // 18
    call(L.weth, SEL.balanceOf + pad(L.pool)),                           // 19
    call(L.wsteth, SEL.balanceOf + pad(L.pool)),                         // 20
    bal(L.syncTrigger),                                                  // 21
  ];
  const r = await rpcBatch(L.rpc, q);
  return {
    wiredPool: decAddr(r[0]), govIsAdmin: decBool(r[1]),
    triggerHasRole: decBool(r[2]), retiredHasRole: decBool(r[3]), oldAutoHasRole: decBool(r[4]),
    proxyOwner: decAddr(r[5]), stOwner: decAddr(r[6]), stForwarder: decAddr(r[7]),
    lastExec: decU(r[8]), delay: decU(r[9]),
    minAmount: r[10] ? BigInt('0x' + r[10].slice(2, 66)) : null,
    maxAmount: r[10] ? BigInt('0x' + r[10].slice(66, 130)) : null,
    maxFees: decU(r[11]), shouldSync: decU(r[12]), canSync: decBool(r[13]),
    creOwner: decAddr(r[14]), creForwarderActual: decAddr(r[15]), creAuthor: decAddr(r[16]),
    callAllowed: decBool(r[17]), poolOwner: decAddr(r[18]),
    poolWeth: decU(r[19]), poolWsteth: decU(r[20]), float: decU(r[21]),
  };
}

async function l1Data() {
  const q = [
    call(L1.receiver, SEL.hasRole + pad(ADMIN_ROLE) + pad(DAO_AGENT)),  // 0
    call(L1.proxyAdmin, SEL.owner),                                     // 1
    bal(L1.receiver),                                                   // 2
    call(L1.wsteth, SEL.balanceOf + pad(L1.receiver)),                  // 3
    call(L1.steth, SEL.balanceOf + pad(L1.receiver)),                   // 4
  ];
  const r = await rpcBatch(L1.rpc, q);
  return { daoIsAdmin: decBool(r[0]), proxyOwner: decAddr(r[1]),
           eth: decU(r[2]), wsteth: decU(r[3]), steth: decU(r[4]) };
}

// ── CRE registration plane (L1 WorkflowRegistry) ─────────────────────────────
// One mainnet registry holds all four lanes' workflows. Read per OWNER and enumerated, so the tab
// keeps working when the pending Safe migration moves ownership — the owner set is discovered from
// each lane's live getExpectedAuthor() rather than hardcoded.
async function registryData(owners) {
  const R = L1.workflowRegistry;
  const q = owners.flatMap(o => [
    call(R, SEL.getWorkflowListByOwner + pad(o) + padU(0) + padU(20)),
    call(R, SEL.isOwnerLinked + pad(o)),
  ]);
  const r = await rpcBatch(L1.rpc, q);
  return owners.map((o, i) => ({
    owner: o,
    workflows: decodeTupleArray(r[i * 2], LAYOUT_WORKFLOW),
    linked: decBool(r[i * 2 + 1]),
  }));
}

// Tuple fields, by index, so the render code never counts positions.
const WF = { id: 0, owner: 1, createdAt: 2, status: 3, name: 4, tag: 7, attributes: 8, donFamily: 9 };

// rpcBatch turns a PER-CALL revert into null while the batch still resolves, so a non-null `regs` does
// not mean the enumeration succeeded. "The registry says no such workflow" and "we could not ask the
// registry" are different claims and only the first may be reported as an absence.
const regsUsable = regs => regs != null && regs.every(a => a.workflows != null);

// The consolidated record, found by OWNER + NAME. Workflow names are owner-scoped, so a same-named
// record under another queried owner must not drive registration, author-gate, or cadence verdicts.
const findConsolidated = regs => !regsUsable(regs) ? null : regs
  .flatMap(acct => acct.workflows.map(t => ({ t })))
  .find(({ t }) => String(t[WF.owner]).toLowerCase() === CRE_WF_OWNER.toLowerCase()
    && t[WF.name] === CRE_WORKFLOW_NAME) ?? null;

// sha256 of the page's own copy of the config, computed rather than asserted: a transcription slip in
// CRE_CONFIG_SHA256 must not be able to pass as agreement with the chain.
const creConfigSha = sha256Hex(CRE_CONFIG_JSON);
const hexOf = b => [...b].map(x => x.toString(16).padStart(2, '0')).join('');
const hexOfText = t => '0x' + hexOf(new TextEncoder().encode(t));
// Three outcomes, not two. What the workflowId commits to is sha256 of the config's BYTES, so a
// re-indented or re-serialised copy of the same parameters is a different artifact even though every
// value matches — worth saying plainly rather than collapsing into "same" or "different".
function paramsAgreement(attrsHex, parsed, repoText, repoParsed) {
  const bytes = String(attrsHex ?? '').toLowerCase() === hexOfText(repoText).toLowerCase();
  if (bytes) return { level: 'ok', label: 'chain = repo', note: 'the record publishes this repo\'s config.deploy.json, byte for byte' };
  const semantic = parsed != null && repoParsed != null && JSON.stringify(parsed) === JSON.stringify(repoParsed);
  if (semantic) return { level: 'warn', label: 'same params, other bytes',
    note: 'every value matches, but the published bytes are not this file\'s — different sha256, so the registered workflowId commits to a different config artifact' };
  return { level: 'crit', label: 'chain ≠ repo', note: 'the deployed parameters differ from config.deploy.json' };
}
const bytesOfHex = h => Uint8Array.from((h || '').replace(/^0x/, '').match(/../g) ?? [], p => parseInt(p, 16));
// What the record's `attributes` turned out to be. Three payloads are recognised — the attestation this
// repo publishes, the older verbatim-config form, and "something else" — because a page that treats an
// unrecognised payload as absent would report a workflow carrying unknown metadata as carrying none.
function parseAttributes(hex) {
  if (!hex || hex === '0x') return { kind: 'empty', bytes: 0 };
  const bytes = (hex.length - 2) / 2;
  let text;
  try { text = new TextDecoder('utf-8', { fatal: true }).decode(bytesOfHex(hex)); }
  catch { return { kind: 'binary', bytes }; }
  let json;
  try { json = JSON.parse(text); } catch { return { kind: 'text', bytes, text }; }
  if (json && json.v === 'cre-attest/3') return { kind: 'attest', bytes, text, a: json };
  // A payload announcing itself as an attestation this page cannot check is NOT treated as one: the
  // fields it carries would be rendered as verified when nothing verified them.
  if (json && typeof json.v === 'string' && json.v.startsWith('cre-attest/'))
    return { kind: 'attest-unknown', bytes, text, a: json };
  if (json && Array.isArray(json.lanes)) return { kind: 'config', bytes, text, config: json };
  return { kind: 'json', bytes, text, json };
}

// Two digests, nothing else — the payload carries no summary hash over itself. Such a value would be
// derivable from the fields beside it, so it could only agree or contradict, and a reader might check
// IT instead of the two digests that carry the meaning.
//
// The compiled binary is deliberately absent too. Two builds of identical sources differ by three bytes
// (javy bakes entropy into its QuickJS snapshot; SOURCE_DATE_EPOCH does not fix it and no CLI flag pins
// it), so a published wasm digest could never be reproduced by a reader — it would render as a check
// while being an assertion, which is the one thing this payload must not do.
// Text arriving from chain or from an explorer is attacker-controlled — the registry's workflowName is
// written by the workflow owner, and this repo's own threat model treats that key as compromised.
const esc = s => String(s ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// ── CRE control plane events (CREReceiver lifecycle) ─────────────────────────
// Matched on topics[0], NOT on Blockscout's `decoded` field: the Linea explorer returns
// `decoded: null` for these events. Every argument this tab shows is indexed, so topics suffice.
const EXEC_TOPIC = '0xbe82131bb3404498c769b0511da41a4ad409fa7152562c2b6669241cbe3bb884';
const EVT = {
  [EXEC_TOPIC]:                                                           { label: 'Report executed', kind: 'exec' },
  '0x3321cda85c145617e47418aa14255e9dcbec53a753778e57591703b89a3cad31':   { label: 'Expected author', kind: 'gate' },
  '0xfbea789d6a139c51ef0f88cde81c3881e90e894fde6c8665726e118af8b13c35':   { label: 'Forwarder', kind: 'gate' },
  '0xb35b8e3487df8622d32523c450283db1844a7a279925f30df21d27bc116189d7':   { label: 'Allowed call', kind: 'gate' },
  '0x94b2de810873337ed265c5f8cf98c9cffefa06b8607f9a2f1fbaebdfbcfbef1c':   { label: 'ETH withdrawn', kind: 'flow' },
  '0x8be0079c531659141344cd1fd0a4f28419497f9722a3daafe3b4186f6b6457e0':   { label: 'Owner', kind: 'gate' },
};

// `CallExecuted` names the call but carries none of its payload: the WETH a sync moved is emitted one
// hop away, by CustomSender's own `Sync(address,uint64,bytes32,uint256)` in the SAME transaction. Read
// it from that log rather than re-deriving it from a pool balance — what moved is a fact OF the
// transaction, while a balance read afterwards is a different claim about a different moment.
// SYNC_TOPIC and syncAmount() below are the ones the Overview tile already reads: one decoder for the
// one event, so a per-sync row and the cumulative total can never disagree about what a Sync says.
const TX_LOG_CONCURRENCY = 6; // one explorer request per historical sync; kept off the explorer's throttle

// Blockscout v2 returns the emitting address as an object here and as a bare string elsewhere.
const logAddr = i => (typeof i?.address === 'string' ? i.address : i?.address?.hash ?? i?.address_hash ?? '');

// Anchored on the CustomSender that emitted it: another contract's Sync in the same transaction is a
// different lane's fact. Returns null when the logs were read and hold no such event.
const syncWeiOf = (logs, L) => {
  const log = (logs ?? []).find(i => (i.topics?.[0] ?? '').toLowerCase() === SYNC_TOPIC
    && logAddr(i).toLowerCase() === L.sender.toLowerCase());
  const amount = log ? syncAmount(log) : null;
  return amount == null ? null : amount.toString();
};

// Three outcomes, three DIFFERENT claims, none allowed to read as another:
//   e.wei = "<decimal>"  → the Sync log was read; this is the amount it names
//   e.wei = null         → the tx's logs were read and hold no Sync from this lane's CustomSender —
//                          an anomaly (the call executed but moved nothing), never shown as `0`
//   e.amtUnread = true   → the source did not answer; unknown, and it says so rather than blank
async function attachSyncAmounts(L, rows) {
  // Amounts are immutable once mined, so a previously read one is re-shown rather than re-fetched;
  // only a successful read (a string) is reused — a null is retried in case the source was lagging.
  const known = new Map((automation.logs[L.name] ?? [])
    .filter(e => typeof e.wei === 'string').map(e => [e.tx, e.wei]));
  // Selector, not target: an exec against the RETIRED trigger moved WETH just the same, and the amount
  // is anchored on the CustomSender that emitted it, not on which trigger was called.
  const syncs = rows.filter(e => e.topic === EXEC_TOPIC && '0x' + (e.topics[2] ?? '').slice(2, 10) === TRIGGER_SYNC_SEL);
  syncs.forEach(e => { if (known.has(e.tx)) e.wei = known.get(e.tx); });
  const todo = syncs.filter(e => e.wei === undefined && e.tx);
  if (!todo.length) return;
  // A lane with no Blockscout of its own (Base) reads receipts from its log-capable RPC instead — the
  // same claim by the only route that lane has. An outage here marks the amounts unread; it must not
  // fail automationLogs and take the lane's whole event history down with it.
  if (!L.bs) {
    let receipts = [];
    try {
      receipts = await rpcBatchChunks(L.logsRpc,
        todo.map(e => ({ method: 'eth_getTransactionReceipt', params: [e.tx] })));
    } catch { todo.forEach(e => { e.amtUnread = true; }); return; }
    todo.forEach((e, i) => {
      const r = receipts[i];
      if (!r || !Array.isArray(r.logs)) { e.amtUnread = true; return; } // unread — NOT "no amount"
      e.wei = syncWeiOf(r.logs, L);
    });
    return;
  }
  for (let i = 0; i < todo.length; i += TX_LOG_CONCURRENCY) {
    await Promise.all(todo.slice(i, i + TX_LOG_CONCURRENCY).map(async e => {
      let items;
      try {
        const res = await fetch(`${L.bs}/api/v2/transactions/${e.tx}/logs`);
        if (!res.ok) { e.amtUnread = true; return; } // unread — NOT "no amount"
        items = (await res.json()).items;
      } catch { e.amtUnread = true; return; }
      if (!Array.isArray(items)) { e.amtUnread = true; return; }
      e.wei = syncWeiOf(items, L);
    }));
  }
}

// The confirmation lag belongs to CURSORS, not to views. syncLogsRange advances a cursor saved in
// localStorage and can never look back, so a log that reorgs out after the cursor passed it is lost
// from the cumulative total for good — that read must stay behind the reorg-able tip. A view that is
// re-read in full every refresh has no such exposure: a reorg simply corrects itself on the next pass.
// On Base (2s blocks, and the only lane read over RPC rather than Blockscout) this window is a full
// HOUR, so applying it to a view would hide exactly the events worth watching — an author-gate change
// stayed invisible for an hour on Base while the other three lanes showed it at once.
const RPC_CONFIRMATIONS = 1800; // a PERSISTED cursor never includes the chain tip
const rpcBlockNumber = async L => Number(BigInt(await rpcRequest(L.logsRpc ?? L.rpc, 'eth_blockNumber', [])));
// The ONLY remaining caller is checkpointedSyncVolumeData, which is the only read that advances a
// persisted cursor. Every other log read below is a full re-read and goes to the tip.
async function rpcSafeBlock(L) {
  return Math.max(0, await rpcBlockNumber(L) - RPC_CONFIRMATIONS);
}

// Reads through the chain tip. Both callers re-read their whole range on every refresh and replace
// their cache wholesale, so a reorg corrects itself on the next pass — while holding back by
// RPC_CONFIRMATIONS would blind them for a full window, an HOUR on Base's 2-second blocks. One
// request, no tip probe: `latest` is resolved by the node.
async function rpcHistoryLogs(L, address, topics, fromBlock) {
  return rpcRequest(L.logsRpc, 'eth_getLogs', [{
    fromBlock: '0x' + fromBlock.toString(16), toBlock: 'latest', address, topics,
  }]);
}

async function automationLogs(L) {
  // The whole CREReceiver history is ~8 events per lane, so one query is the full record.
  let rows;
  if (L.logsRpc) {
    const logs = await rpcHistoryLogs(L, L.creReceiver, [[...Object.keys(EVT)]], L.activityFrom);
    rows = logs.map(i => ({
      topic: i.topics[0].toLowerCase(), topics: i.topics.map(t => t && t.toLowerCase()),
      data: i.data, block: Number(BigInt(i.blockNumber)), tx: i.transactionHash, ts: null,
    }));
  } else {
    const res = await fetch(`${L.bs}/api/v2/addresses/${L.creReceiver}/logs`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const page = await res.json();
    rows = (page.items ?? [])
      .filter(i => EVT[(i.topics?.[0] ?? '').toLowerCase()])
      .map(i => ({
        topic: i.topics[0].toLowerCase(), topics: i.topics.map(t => t && t.toLowerCase()),
        data: i.data, block: i.block_number, tx: i.transaction_hash,
        ts: i.block_timestamp ? Math.floor(Date.parse(i.block_timestamp) / 1000) : null,
      }));
  }
  // Linea's explorer also omits block_timestamp here; backfill from the lane's own RPC by block.
  const missing = [...new Set(rows.filter(r => r.ts == null && r.block != null).map(r => r.block))];
  if (missing.length) {
    const calls = missing.map(n =>
      ({ method: 'eth_getBlockByNumber', params: ['0x' + n.toString(16), false] }));
    const blocks = L.logsRpc ? await rpcBatchChunks(L.logsRpc, calls) : await rpcBatch(L.rpc, calls);
    const stamps = new Map(missing.map((n, i) => [n, blocks[i]?.timestamp ? Number(BigInt(blocks[i].timestamp)) : null]));
    rows.forEach(r => { if (r.ts == null) r.ts = stamps.get(r.block) ?? null; });
  }
  await attachSyncAmounts(L, rows);
  return rows.sort((a, b) => (b.ts ?? 0) - (a.ts ?? 0));
}

// ── Derivations ──────────────────────────────────────────────────────────────
// Checks grouped by the contract they read from (group.addr → explorer link).
function laneGroups(L, d) {
  const eq = (a, b) => a && a.toLowerCase() === b.toLowerCase();
  const cell = ([level, value], a) => ({ level, value, a: a ? a.toLowerCase() : null }); // a → holder address, linked in the matrix
  const syncRole = d.retiredHasRole || d.oldAutoHasRole ? ['crit', 'legacy holder'] // revoked at migration; a regrant = compromise
    : d.triggerHasRole ? ['ok', 'SyncTrigger'] : ['crit', 'missing'];
  return [
    { contract: 'CustomSender', addr: L.sender, checks: [
      { key: 'wired pool', sub: 'getOraclePool()', ...cell(eq(d.wiredPool, L.pool) ? ['ok', holder(L.pool, 'OraclePool')] : ['crit', holder(d.wiredPool)], d.wiredPool) },
      { key: 'admin', sub: 'DEFAULT_ADMIN_ROLE', ...cell(d.govIsAdmin ? ['ok', holder(L.gov, 'Gov Executor')] : ['crit', 'not Gov Executor'], d.govIsAdmin ? L.gov : null) },
      { key: 'sync role', sub: 'hasRole(SYNC_ROLE)', ...cell(syncRole[1] === 'SyncTrigger' ? [syncRole[0], holder(L.syncTrigger, 'SyncTrigger')] : syncRole, L.syncTrigger) },
    ] },
    { contract: 'ProxyAdmin', addr: L.proxyAdmin, checks: [
      { key: 'owner', sub: 'owner()', ...cell(eq(d.proxyOwner, L.gov) ? ['ok', holder(L.gov, 'Gov Executor')] : ['crit', holder(d.proxyOwner)], d.proxyOwner) },
    ] },
    { contract: 'SyncTrigger', addr: L.syncTrigger, checks: [
      { key: 'owner', sub: 'owner()', ...cell(ownerCheck(d.stOwner, ST_OWNER), d.stOwner) },
      { key: 'forwarder', sub: 'getForwarder()', ...cell(eq(d.stForwarder, L.creReceiver) ? ['ok', holder(L.creReceiver, 'CREReceiver')] : ['crit', holder(d.stForwarder)], d.stForwarder) },
    ] },
    { contract: 'CREReceiver', addr: L.creReceiver, checks: [
      { key: 'owner', sub: 'owner()', ...cell(ownerCheck(d.creOwner, ST_OWNER), d.creOwner) },
      { key: 'forwarder', sub: 'getForwarder()', ...cell(eq(d.creForwarderActual, L.creForwarder) ? ['ok', holder(L.creForwarder, 'CRE Forwarder')] : ['crit', holder(d.creForwarderActual)], d.creForwarderActual) },
      { key: 'expected author', sub: 'getExpectedAuthor()', ...cell(ownerCheck(d.creAuthor, CRE_AUTHOR), d.creAuthor) },
      { key: 'triggerSync allowed', sub: 'isCallAllowed()', ...cell(d.callAllowed ? ['ok', 'allowed'] : ['crit', 'blocked']) },
    ] },
    { contract: 'OraclePool', addr: L.pool, checks: [
      { key: 'owner', sub: 'owner()', ...cell(ownerCheck(d.poolOwner, LOL), d.poolOwner) },
    ] },
  ];
}
const laneChecks = (L, d) => laneGroups(L, d).flatMap(g => g.checks);

// Why canSync() is false — same gates the contract checks, named from data we already read.
function canSyncCause(d) {
  if (d.triggerHasRole === false) return 'SYNC_ROLE lost';
  if (d.float != null && d.maxFees != null && d.float < d.maxFees) return 'float below maxFees';
  return 'pool paused'; // the only remaining canSync gate
}

function syncState(d) {
  if (d.shouldSync == null || d.canSync == null) return ['crit', 'UNREADABLE', 'probe failed'];
  if (d.shouldSync > 0n && !d.canSync) return ['crit', 'BLOCKED', fmtEth(d.shouldSync, 2) + ' WETH due — ' + canSyncCause(d)];
  if (d.shouldSync > 0n) return ['warn', 'DUE', fmtEth(d.shouldSync, 2) + ' WETH, awaiting DON'];
  if (!d.canSync) return ['warn', 'IMPAIRED', canSyncCause(d)];
  if (d.delay != null && d.lastExec != null && BigInt(Math.floor(Date.now() / 1000)) < d.lastExec + d.delay)
    return ['ok', 'COOLDOWN', 'delay window active'];
  return ['ok', 'IDLE', 'pool below min amount'];
}

function floatState(d) {
  if (d.float == null || d.maxFees == null || d.maxFees === 0n) return { level: 'crit', x: null };
  const x = Number(d.float) / Number(d.maxFees);
  return { level: x >= 1.5 ? 'ok' : x >= 1 ? 'warn' : 'crit', x };
}

function l1AccessChecks(d) {
  const [pl, pv] = ownerCheck(d.proxyOwner, DAO_AGENT);
  return [
    { key: 'Receiver admin', level: d.daoIsAdmin ? 'ok' : 'crit',
      value: d.daoIsAdmin ? holder(DAO_AGENT) : 'not DAO Agent', sub: 'DEFAULT_ADMIN_ROLE' },
    { key: 'ProxyAdmin owner', level: pl, value: pv, sub: 'owner()' },
  ];
}

function l1BalanceChecks(d) {
  const balRow = (label, v) => ({
    key: label,
    ...(v == null ? { level: 'crit', value: 'unreadable', sub: '' }
      : v > 10n ** 18n ? { level: 'crit', value: fmtEth(v) + ' ETH', sub: 'parked > 1' }
      : v > 10n ** 12n ? { level: 'warn', value: fmtEth(v, 6), sub: 'transient?' }
      : { level: 'ok', value: '~0', sub: 'as expected' }),
  });
  return [
    balRow('Receiver ETH', d.eth), balRow('Receiver wstETH', d.wsteth), balRow('Receiver stETH', d.steth),
  ];
}

// ── Pool activity ────────────────────────────────────────────────────────────
// Explorer transfers and CustomSender SlowStake events across all four lanes.
const eqa = (a, b) => !!a && !!b && a.toLowerCase() === b.toLowerCase();
const ZERO = '0x' + '0'.repeat(40);
const fmtAmt = wei => {
  const value = fmtEth(wei, wei > 0n && wei < 10n ** 15n ? 8 : 4);
  return wei > 0n && value === '0' ? '<0.00000001' : value;
};
const SLOW_STAKE_TOPIC = '0xb9a1909fb1e8f533ab60d262ba908dc82a1d8dfaef2e6c4e4b2da76de8a1ca4d';
const SYNC_TOPIC = '0x2826f7440c9ba1050bcd2c586a60551875ac8951ec73f01df55ef00b59ae1a9c';
const TRANSFER_TOPIC = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef';

async function poolActivityData(L) {
  if (L.logsRpc) return rpcPoolActivityData(L);
  const byTx = new Map();
  const base = `${L.bs}/api/v2/addresses/${L.pool}/token-transfers`;
  let nextPage = {};
  while (nextPage && byTx.size < 50) {
    const url = new URL(base);
    Object.entries(nextPage).forEach(([key, value]) => url.searchParams.set(key, value));
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const page = await res.json();
    for (const t of page.items ?? []) {
      const g = byTx.get(t.transaction_hash) ??
        { tx: t.transaction_hash, ts: Date.parse(t.timestamp) / 1000 || 0, in: [], out: [] };
      const addr = t.token.address_hash ?? t.token.address;
      // only the canonical WETH/wstETH — spam airdrops carry attacker-controlled symbols
      const token = eqa(addr, L.weth) ? 'WETH' : eqa(addr, L.wsteth) ? 'wstETH' : null;
      if (!token) continue;
      (eqa(t.to.hash, L.pool) ? g.in : g.out)
        .push({ token, amount: BigInt(t.total.value), from: t.from.hash, to: t.to.hash });
      byTx.set(t.transaction_hash, g);
    }
    nextPage = page.next_page_params;
  }
  return [...byTx.values()].slice(0, 50).map(g => classifyTx(L, g));
}

async function rpcPoolActivityData(L) {
  // ONE tip read, shared by both queries below. They are separate eth_getLogs calls, so letting each
  // resolve `latest` for itself would let a transfer fall inside one range and outside the other —
  // and classifyTx would then read a transaction from half its legs, labelling a fast stake as a bare
  // "WETH in". A pinned number keeps the pair range-consistent; the confirmation window does not
  // belong here, since this whole range is re-read and the lane's cache replaced on every refresh.
  const toBlock = await rpcBlockNumber(L);
  if (toBlock < L.activityFrom) return [];
  const poolTopic = '0x' + '0'.repeat(24) + L.pool.slice(2).toLowerCase();
  const filter = topics => ({ fromBlock: '0x' + L.activityFrom.toString(16),
    toBlock: '0x' + toBlock.toString(16), address: [L.weth, L.wsteth], topics });
  const [outbound, inbound] = await Promise.all([
    rpcRequest(L.logsRpc, 'eth_getLogs', [filter([TRANSFER_TOPIC, poolTopic])]),
    rpcRequest(L.logsRpc, 'eth_getLogs', [filter([TRANSFER_TOPIC, null, poolTopic])]),
  ]);
  const byTx = new Map();
  const seen = new Set();
  for (const log of [...outbound, ...inbound]) {
    const key = `${log.transactionHash}:${log.logIndex}`;
    if (seen.has(key) || (log.topics?.[0] ?? '').toLowerCase() !== TRANSFER_TOPIC ||
        !/^0x[0-9a-f]{64}$/i.test(log.data ?? '')) continue;
    seen.add(key);
    const from = topicAddress(log.topics[1]), to = topicAddress(log.topics[2]);
    const token = eqa(log.address, L.weth) ? 'WETH' : eqa(log.address, L.wsteth) ? 'wstETH' : null;
    if (!from || !to || !token) continue;
    const g = byTx.get(log.transactionHash) ?? { tx: log.transactionHash,
      block: Number(BigInt(log.blockNumber)), ts: 0, in: [], out: [] };
    (eqa(to, L.pool) ? g.in : g.out).push({ token, amount: BigInt(log.data), from, to });
    byTx.set(log.transactionHash, g);
  }
  const groups = [...byTx.values()].sort((a, b) => b.block - a.block).slice(0, 50);
  const blockNumbers = [...new Set(groups.map(g => g.block))];
  const blocks = blockNumbers.length ? await rpcBatchChunks(L.logsRpc, blockNumbers.map(n =>
    ({ method: 'eth_getBlockByNumber', params: ['0x' + n.toString(16), false] }))) : [];
  const stamps = new Map(blockNumbers.map((n, i) =>
    [n, blocks[i]?.timestamp ? Number(BigInt(blocks[i].timestamp)) : 0]));
  groups.forEach(g => { g.ts = stamps.get(g.block) ?? 0; });
  return groups.map(g => classifyTx(L, g));
}

const topicAddress = topic => /^0x[0-9a-f]{64}$/i.test(topic ?? '') ? '0x' + topic.slice(-40) : null;

function parseSlowStakeLog(L, log) {
  const topics = log.topics ?? [];
  const data = log.data ?? '';
  const tx = log.transactionHash ?? '';
  if ((topics[0] ?? '').toLowerCase() !== SLOW_STAKE_TOPIC ||
      !/^0x[0-9a-f]{128}$/i.test(data) || !/^0x[0-9a-f]{64}$/i.test(tx)) return null;
  const user = topicAddress(topics[1]);
  const token = topicAddress(topics[3]);
  if (!user || !eqa(token, L.weth)) return null;
  const rawTs = log.timeStamp;
  const parsedTs = typeof rawTs === 'number' ? rawTs
    : /^(0x[0-9a-f]+|\d+)$/i.test(rawTs ?? '') ? Number(BigInt(rawTs)) : 0;
  const amount = BigInt('0x' + data.slice(66, 130));
  return { tx, ts: parsedTs,
    kind: 'stake', label: 'Slow stake', amount: `${fmtAmt(amount)} WETH → L1`, cp: user };
}

async function blockscoutAddressLogs(base, address, topic, { limit = Infinity, since = null, accept = () => true } = {}) {
  const rows = [];
  const normalizedTopic = topic.toLowerCase();
  let nextPage = {};
  for (let pageNumber = 0; nextPage && pageNumber < 100; pageNumber++) {
    const url = new URL(`${base}/api/v2/addresses/${address}/logs`);
    url.searchParams.set('topic', topic);
    Object.entries(nextPage).forEach(([key, value]) => url.searchParams.set(key, value));
    const res = await rpcFetch(url.toString());
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const page = await res.json();
    if (!Array.isArray(page.items)) throw new Error('invalid logs response');
    const logs = page.items
      .filter(item => (item.topics?.[0] ?? '').toLowerCase() === normalizedTopic)
      .map(item => ({
      topics: item.topics, data: item.data,
      blockNumber: item.block_number, logIndex: item.index,
      transactionHash: item.transaction_hash,
      timeStamp: item.block_timestamp ? Math.floor(Date.parse(item.block_timestamp) / 1000) : null,
    }));
    for (const log of logs) {
      if (since != null) {
        if (!Number.isFinite(log.timeStamp)) throw new Error('receiver event timestamp unavailable');
        if (log.timeStamp < since) return rows;
      }
      if (accept(log)) rows.push(log);
      if (rows.length >= limit) return rows;
    }
    nextPage = page.next_page_params;
  }
  if (nextPage) throw new Error('log history exceeds 5,000 rows');
  return rows;
}

async function senderLogs(L, topic, options) {
  if (L.v2Logs) return blockscoutAddressLogs(L.bs, L.sender, topic, options);
  if (L.logsRpc && !L.bs) {
    const logs = await rpcHistoryLogs(L, L.sender, [topic], L.senderFrom);
    const blockNumbers = [...new Set(logs.map(log => Number(BigInt(log.blockNumber))))];
    const blocks = blockNumbers.length ? await rpcBatchChunks(L.logsRpc, blockNumbers.map(n =>
      ({ method: 'eth_getBlockByNumber', params: ['0x' + n.toString(16), false] }))) : [];
    const stamps = new Map(blockNumbers.map((n, i) =>
      [n, blocks[i]?.timestamp ? blocks[i].timestamp : null]));
    return logs.map(log => ({ ...log, timeStamp: stamps.get(Number(BigInt(log.blockNumber))) }));
  }
  const url = new URL(`${L.bs}/api`);
  Object.entries({ module: 'logs', action: 'getLogs', fromBlock: 0, toBlock: 'latest',
    address: L.sender, topic0: topic }).forEach(([key, value]) => url.searchParams.set(key, value));
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const page = await res.json();
  if (!Array.isArray(page.result)) throw new Error(page.message || 'invalid logs response');
  return page.result;
}

async function slowStakeData(L) {
  const logs = await senderLogs(L, SLOW_STAKE_TOPIC, { limit: 50, accept: log => !!parseSlowStakeLog(L, log) });
  return logs.map(log => parseSlowStakeLog(L, log)).filter(Boolean);
}

const SYNC_PROGRESS_KEY = 'direct-staking-watch.sync-progress';
function readSyncProgress(L) {
  const seed = L.syncCheckpoint;
  try {
    const all = JSON.parse(localStorage.getItem(SYNC_PROGRESS_KEY));
    const saved = all?.[L.name];
    if (Number.isSafeInteger(saved?.block) && saved.block >= seed.block &&
        Number.isSafeInteger(saved?.count) && saved.count >= seed.count &&
        /^\d+$/.test(saved?.wei ?? '') && BigInt(saved.wei) >= BigInt(seed.wei)) return saved;
  } catch {}
  return seed;
}

function saveSyncProgress(L, progress) {
  try {
    const all = JSON.parse(localStorage.getItem(SYNC_PROGRESS_KEY)) || {};
    all[L.name] = progress;
    localStorage.setItem(SYNC_PROGRESS_KEY, JSON.stringify(all));
  } catch {}
}

const syncAmount = log => (log.topics?.[0] ?? '').toLowerCase() === SYNC_TOPIC &&
  /^0x[0-9a-f]{128}$/i.test(log.data ?? '') ? BigInt('0x' + log.data.slice(66, 130)) : null;

// Cumulative CustomSender.Sync totals were verified through these per-lane checkpoint blocks on
// 2026-08-20. Only the immutable tail after each block is read on load; localStorage advances the
// cursor after every successful refresh.
async function syncLogsRange(L, fromBlock, toBlock) {
  if (L.logsRpc) return rpcRequest(L.logsRpc, 'eth_getLogs', [{
    fromBlock: '0x' + fromBlock.toString(16), toBlock: '0x' + toBlock.toString(16),
    address: L.sender, topics: [SYNC_TOPIC],
  }]);
  const url = new URL(`${L.bs}/api`);
  Object.entries({ module: 'logs', action: 'getLogs', fromBlock, toBlock,
    address: L.sender, topic0: SYNC_TOPIC }).forEach(([key, value]) => url.searchParams.set(key, value));
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const page = await res.json();
  if (!Array.isArray(page.result)) throw new Error(page.message || 'invalid logs response');
  return page.result;
}

async function checkpointedSyncVolumeData(L) {
  const progress = readSyncProgress(L);
  const toBlock = await rpcSafeBlock(L);
  if (toBlock <= progress.block) return { wei: BigInt(progress.wei), count: progress.count };
  const logs = await syncLogsRange(L, progress.block + 1, toBlock);
  const unique = [...new Map(logs.map(log => [`${log.transactionHash}:${log.logIndex}`, log])).values()];
  const amounts = unique.map(syncAmount).filter(amount => amount != null);
  const next = { block: toBlock,
    wei: (BigInt(progress.wei) + amounts.reduce((sum, amount) => sum + amount, 0n)).toString(),
    count: progress.count + amounts.length };
  saveSyncProgress(L, next);
  return { wei: BigInt(next.wei), count: next.count };
}

async function syncVolumeData(L) {
  if (L.syncCheckpoint) return checkpointedSyncVolumeData(L);
  const logs = await senderLogs(L, SYNC_TOPIC);
  const amounts = logs.map(syncAmount).filter(amount => amount != null);
  return { wei: amounts.reduce((sum, amount) => sum + amount, 0n), count: amounts.length };
}

function cachedSyncVolume() {
  const progress = LANES.map(readSyncProgress);
  return { readable: progress.length, cached: true,
    wei: progress.reduce((sum, item) => sum + BigInt(item.wei), 0n),
    count: progress.reduce((sum, item) => sum + item.count, 0) };
}

async function activityData(L) {
  const [pool, slowStakes] = await Promise.all([
    poolActivityData(L).catch(e => { throw new Error(`pool: ${e.message}`); }),
    slowStakeData(L).catch(e => { throw new Error(`SlowStake: ${e.message}`); }),
  ]);
  return [...pool, ...slowStakes].sort((a, b) => b.ts - a.ts).slice(0, 50);
}

function classifyTx(L, g) {
  const find = (legs, token) => legs.find(l => l.token === token);
  const wIn = find(g.in, 'WETH'), wsOut = find(g.out, 'wstETH');
  const wOut = find(g.out, 'WETH'), wsIn = find(g.in, 'wstETH');
  const base = { tx: g.tx, ts: g.ts };
  if (wIn && wsOut) return { ...base, kind: 'stake', label: 'Fast stake',
    amount: `${fmtAmt(wIn.amount)} WETH → ${fmtAmt(wsOut.amount)} wstETH`, cp: wsOut.to };
  if (wOut) return eqa(wOut.to, L.sender)
    ? { ...base, kind: 'sync', label: 'Sync → L1', amount: `−${fmtAmt(wOut.amount)} WETH`, cp: wOut.to }
    : { ...base, kind: 'flow', label: 'WETH out', amount: `−${fmtAmt(wOut.amount)} WETH`, cp: wOut.to };
  if (wsIn) return { ...base, kind: 'flow', label: eqa(wsIn.from, ZERO) ? 'Top-up · bridge' : 'Top-up',
    amount: `+${fmtAmt(wsIn.amount)} wstETH`, cp: wsIn.from };
  if (wsOut) return { ...base, kind: 'flow', label: 'wstETH out', amount: `−${fmtAmt(wsOut.amount)} wstETH`, cp: wsOut.to };
  return { ...base, kind: 'flow', label: 'WETH in', amount: `+${fmtAmt(wIn.amount)} WETH`, cp: wIn.from };
}

const ACTIVITY_SEEN_KEY = 'direct-staking-watch.activity-seen';
const ACTIVITY_CACHE_KEY = 'direct-staking-watch.activity-cache';
let latestActivity = null;
let activitySeen = readActivitySeen();
let activityFailed = false;
let activityCache = readActivityCache();
// Rows newer than this marker render highlighted; it advances when the tab is (re)opened,
// so the highlight survives auto-refreshes while the user is looking at the table.
let activityViewBoundary = readActivitySeen();
let lastActivityResults = null;
let activityRenderedAt = null;
let syncVolume = cachedSyncVolume();
let syncVolumeRefreshing = true;

function syncVolumeStatus() {
  if (!syncVolume) return { level: 'tinted', loading: true, value: '', sub: 'reading CustomSender history' };
  if (!syncVolume.readable) return { level: 'critical', value: 'unread', sub: 'no lane history readable' };
  const partial = syncVolume.readable < LANES.length;
  return { level: partial ? 'warning' : 'tinted',
    refreshing: syncVolumeRefreshing,
    value: `${partial || syncVolume.cached ? '≥ ' : ''}${fmtEth(syncVolume.wei, 2)} <span class="unit">WETH</span>`,
    sub: `${syncVolume.count} sync${syncVolume.count === 1 ? '' : 's'}` };
}

const syncVolumeValue = status => status.loading
  ? '<span class="spin" aria-hidden="true"></span><span>Loading</span>'
  : status.value;

function updateSyncVolumeTile() {
  const tile = document.getElementById('sync-volume');
  if (!tile) return;
  const status = syncVolumeStatus();
  tile.classList.toggle('tinted', status.level === 'tinted');
  tile.classList.toggle('warning', status.level === 'warning');
  tile.classList.toggle('critical', status.level === 'critical');
  const value = tile.querySelector('.v');
  value.classList.toggle('loading', !!status.loading);
  value.setAttribute('aria-busy', String(!!status.loading || status.refreshing));
  value.innerHTML = syncVolumeValue(status);
  tile.querySelector('.sync-volume-text').textContent = status.sub;
  tile.querySelector('.sync-volume-sub .spin').hidden = !status.refreshing;
}

// Last successful per-lane events; instant paint on load, fallback while a source is down.
function readActivityCache() {
  try {
    const cache = JSON.parse(localStorage.getItem(ACTIVITY_CACHE_KEY));
    return cache && typeof cache === 'object' ? cache : {};
  } catch { return {}; }
}

function saveActivityCache() {
  try { localStorage.setItem(ACTIVITY_CACHE_KEY, JSON.stringify(activityCache)); } catch {}
}

function readActivitySeen() {
  try {
    const marker = JSON.parse(localStorage.getItem(ACTIVITY_SEEN_KEY));
    return marker && Number.isFinite(marker.ts) && Array.isArray(marker.txs) ? marker : null;
  } catch { return null; }
}

function saveActivitySeen() {
  try { localStorage.setItem(ACTIVITY_SEEN_KEY, JSON.stringify(activitySeen)); } catch {}
}

function hasUnseenActivity() {
  if (!latestActivity || !activitySeen) return false;
  return latestActivity.ts > activitySeen.ts ||
    latestActivity.ts === activitySeen.ts && latestActivity.txs.some(tx => !activitySeen.txs.includes(tx));
}

function updateActivityTabStatus() {
  setTabStatus('activity', activityFailed ? 'crit' : hasUnseenActivity() ? 'new' : null);
}

function markActivitySeen() {
  if (latestActivity) {
    activitySeen = latestActivity;
    saveActivitySeen();
  }
  updateActivityTabStatus();
}

function renderActivity(results) {
  const failed = results.filter(r => r.error).map(r => `${r.L.name} (${r.error})`);
  const stale = results.some(r => r.error && r.events);
  const rows = results.filter(r => r.events)
    .flatMap(r => r.events.map(e => ({ L: r.L, ...e })))
    .sort((a, b) => b.ts - a.ts).slice(0, 60);
  activityFailed = failed.length > 0;
  latestActivity = rows.length ? {
    ts: rows[0].ts,
    txs: rows.filter(r => r.ts === rows[0].ts).map(r => r.tx).sort(),
  } : null;
  if (!activitySeen && latestActivity) {
    activitySeen = latestActivity;
    saveActivitySeen();
  }
  if (activeTab === 'activity') markActivitySeen();
  else updateActivityTabStatus();
  lastActivityResults = results;
  const isFresh = e => !!activityViewBoundary && (e.ts > activityViewBoundary.ts ||
    e.ts === activityViewBoundary.ts && !activityViewBoundary.txs.includes(e.tx));
  const tr = rows.map(e => `<tr${isFresh(e) ? ' class="fresh"' : ''}>
    <td><span class="num"><div class="m">${ago(e.ts)}</div><div class="s">${new Date(e.ts * 1000).toLocaleString()}</div></span></td>
    <td><span class="who"><span class="avatar">${netLogo(e.L)}</span><span class="name">${e.L.name}</span></span></td>
    <td><span class="tag ${e.kind}">${e.label}</span></td>
    <td><span class="num"><div class="m">${e.amount}</div></span></td>
    <td><span class="who">${alink(e.L, e.cp, NAMES[e.cp.toLowerCase()] && !eqa(e.cp, ZERO) ? holder(e.cp) : undefined)}</span></td>
    <td><a href="${e.L.explorer}/tx/${e.tx}" target="_blank" title="${e.tx}" class="mono">${short(e.tx)}&thinsp;↗</a></td>
  </tr>`).join('');
  document.getElementById('activity').innerHTML = `<div class="card">
    <div class="card-head">
      <h3>Pool Activity</h3>
      <span class="desc">Latest pool transactions across all lanes.</span>
      <span class="upd" id="activity-upd" role="status" aria-live="polite"></span>
      ${viewRefresh('activity', 'Pool activity')}
    </div>
    ${failed.length ? `<div class="err-banner">✕ Activity source unavailable: ${failed.join(', ')}${stale ? ' · showing cached activity' : ''}<button class="retry" onclick="this.disabled=true;refreshActivity()">⟳ retry</button></div>` : ''}
    ${rows.length ? `<div class="scroll-x"><table>
      <tr><th>Age</th><th>Lane</th><th>Action</th><th>Amount</th><th>Counterparty</th><th>Tx</th></tr>
      ${tr}</table></div>` : failed.length ? '' : '<div class="err-banner">no transfers found</div>'}
  </div>`;
  updateActivityUpd();
}

function updateActivityUpd() {
  const el = document.getElementById('activity-upd');
  if (!el) return;
  const busy = !!refreshAllPromise || refreshingViews.has('activity');
  el.innerHTML = busy ? '<span class="spin" aria-hidden="true"></span>updating…'
    : activityRenderedAt ? `updated ${ago(Math.floor(activityRenderedAt / 1000))}` : '';
}
setInterval(updateActivityUpd, 10_000);

// ── Shuttle failures ────────────────────────────────────────────────────────
// MessageFailed discovers the incident and carries the complete CCIP message. Contract state and
// lifecycle events provide the current verdict; an old failure event alone must never look active.
const MESSAGE_FAILED_TOPIC = '0xef8a84d7e9c9d42c79a42cba16e93688c646989f43846843e163672cc887e253';
const MESSAGE_RECOVERED_TOPIC = '0xef3bf8c64bc480286c4f3503b870ceb23e648d2d902e31fb7bb46680da6de8ad';
const TOKENS_RECOVERED_TOPIC = '0x6e2f4b2b871174c4882a9b21bf5a2f421274d3dba05cc997af4528bdc393c027';
const ZERO32 = '0x' + '0'.repeat(64);
const FAILURES_SINCE = Date.parse('2026-08-01T00:00:00Z') / 1000;

const logQuantity = value => {
  try {
    if (typeof value === 'number') return Number.isSafeInteger(value) ? value : null;
    if (/^(0x[0-9a-f]+|\d+)$/i.test(value ?? '')) {
      const n = Number(BigInt(value));
      return Number.isSafeInteger(n) ? n : null;
    }
  } catch {}
  return null;
};

function parseFailedMessageLog(log) {
  const body = (log.data ?? '').replace(/^0x/, '');
  const topics = log.topics ?? [];
  const eventId = (topics[1] ?? '').toLowerCase();
  const tx = (log.transactionHash ?? '').toLowerCase();
  if ((topics[0] ?? '').toLowerCase() !== MESSAGE_FAILED_TOPIC ||
      !/^0x[0-9a-f]{64}$/.test(eventId) || !/^0x[0-9a-f]{64}$/.test(tx) ||
      !/^[0-9a-f]+$/i.test(body) || body.length % 64) return null;

  const words = body.length / 64;
  const word = i => {
    if (!Number.isSafeInteger(i) || i < 0 || i >= words) throw new Error('short event data');
    return body.slice(i * 64, i * 64 + 64);
  };
  const uint = i => BigInt('0x' + word(i));
  const relative = (base, slot) => {
    const offset = Number(uint(slot));
    if (!Number.isSafeInteger(offset) || offset % 32) throw new Error('invalid event offset');
    return base + offset / 32;
  };
  const bytes = (base, slot) => {
    const at = relative(base, slot);
    const length = Number(uint(at));
    if (!Number.isSafeInteger(length)) throw new Error('invalid bytes length');
    const start = (at + 1) * 64;
    const value = body.slice(start, start + length * 2);
    if (value.length !== length * 2) throw new Error('short bytes value');
    return value;
  };

  try {
    const tuple = relative(0, 0);
    const messageId = ('0x' + word(tuple)).toLowerCase();
    if (messageId !== eventId) return null;
    const sourceSelector = uint(tuple + 1).toString();
    bytes(tuple, tuple + 2); // validate the sender offset even though the receiver already authenticated it
    const payload = bytes(tuple, tuple + 3);
    const tokenArray = relative(tuple, tuple + 4);
    const tokenCount = Number(uint(tokenArray));
    const maxTokenCount = Math.floor((words - tokenArray - 1) / 2);
    if (!Number.isSafeInteger(tokenCount) || tokenCount < 0 || tokenCount > maxTokenCount) return null;
    const tokens = Array.from({ length: tokenCount }, (_, i) => ({
      token: '0x' + word(tokenArray + 1 + i * 2).slice(-40),
      amount: uint(tokenArray + 2 + i * 2),
    }));
    const block = logQuantity(log.blockNumber), logIndex = logQuantity(log.logIndex);
    if (block == null || logIndex == null) return null;
    return {
      messageId, sourceSelector, tx, block, logIndex, timestamp: logQuantity(log.timeStamp),
      recipient: payload.length >= 104 ? '0x' + payload.slice(0, 40) : null,
      amount: payload.length >= 104 ? BigInt('0x' + payload.slice(40, 104)) : null,
      tokens,
    };
  } catch { return null; }
}

function parseFailedLifecycleLog(log) {
  const topic = (log.topics?.[0] ?? '').toLowerCase();
  const messageId = (log.topics?.[1] ?? '').toLowerCase();
  const tx = (log.transactionHash ?? '').toLowerCase();
  const block = logQuantity(log.blockNumber), logIndex = logQuantity(log.logIndex);
  const kind = topic === MESSAGE_RECOVERED_TOPIC ? 'retried'
    : topic === TOKENS_RECOVERED_TOPIC ? 'recovered' : null;
  if (!kind || !/^0x[0-9a-f]{64}$/.test(messageId) || !/^0x[0-9a-f]{64}$/.test(tx) ||
      block == null || logIndex == null) return null;
  return { kind, messageId, tx, block, logIndex, timestamp: logQuantity(log.timeStamp) };
}

async function l1ReceiverLogs(topic, toBlock) {
  return (await blockscoutAddressLogs(L1.bs, L1.receiver, topic, { since: FAILURES_SINCE }))
    .filter(log => log.blockNumber <= toBlock);
}

async function blockscoutIndexedBlock() {
  const res = await rpcFetch(`${L1.bs}/api/v2/stats`);
  if (!res.ok) throw new Error(`index status HTTP ${res.status}`);
  const indexedBlock = logQuantity((await res.json()).total_blocks);
  if (indexedBlock == null) throw new Error('indexed block unreadable');
  return indexedBlock;
}

async function failedMessageData() {
  const [rpcHead, indexedHead] = await Promise.all([rpcBlockNumber(L1), blockscoutIndexedBlock()]);
  const maxIndexLag = 64;
  if (rpcHead - indexedHead > maxIndexLag)
    throw new Error(`L1 indexer is ${rpcHead - indexedHead} blocks behind RPC (maximum ${maxIndexLag})`);
  const atBlock = Math.min(rpcHead, indexedHead);
  const failedLogs = await l1ReceiverLogs(MESSAGE_FAILED_TOPIC, atBlock);
  const retriedLogs = await l1ReceiverLogs(MESSAGE_RECOVERED_TOPIC, atBlock);
  const recoveredLogs = await l1ReceiverLogs(TOKENS_RECOVERED_TOPIC, atBlock);
  const decoded = failedLogs.map(parseFailedMessageLog);
  const lifecycle = [...retriedLogs, ...recoveredLogs].map(parseFailedLifecycleLog);
  if (decoded.some(message => !message) || lifecycle.some(event => !event))
    throw new Error('unrecognized receiver event');
  if (decoded.some(message => message.timestamp == null))
    throw new Error('receiver event timestamp unavailable');
  const messages = [...new Map(decoded.filter(message => message.timestamp >= FAILURES_SINCE)
    .map(message => [message.messageId, message])).values()];
  const hashes = await rpcBatch(L1.rpc, messages.map(message => ({ method: 'eth_call', params: [{
    to: L1.receiver, data: SEL.failedMessageHash + message.messageId.slice(2),
  }, '0x' + atBlock.toString(16)] })));
  if (hashes.some(hash => !/^0x[0-9a-f]{64}$/i.test(hash ?? '')))
    throw new Error('failed-message state unreadable');
  return messages.map((message, i) => {
    const later = lifecycle.filter(event => event.messageId === message.messageId &&
      (event.block > message.block || event.block === message.block && event.logIndex > message.logIndex))
      .sort((a, b) => b.block - a.block || b.logIndex - a.logIndex)[0] ?? null;
    const failedHash = hashes[i].toLowerCase();
    return { ...message, failedHash, lifecycle: later,
      state: failedHash !== ZERO32 ? 'active' : later?.kind ?? 'unknown' };
  });
}

function renderShuttles(messages, error) {
  if (error) {
    setTabStatus('shuttle', 'crit');
    document.getElementById('shuttle').innerHTML = `<div class="card">
      <div class="card-head"><h3>L1 receiver failures</h3>${viewRefresh('shuttle', 'Shuttle failures')}</div>
      <div class="err-banner">✕ ${esc(error)}</div></div>`;
    return;
  }
  const active = messages.filter(message => message.state === 'active');
  const unknown = messages.filter(message => message.state === 'unknown');
  const retried = messages.filter(message => message.state === 'retried');
  const recovered = messages.filter(message => message.state === 'recovered');
  const ordered = [...messages].sort((a, b) => (b.timestamp ?? 0) - (a.timestamp ?? 0) ||
    b.block - a.block || b.logIndex - a.logIndex);
  setTabStatus('shuttle', unknown.length ? 'crit' : active.length ? 'warn' : null);
  const rows = ordered.map(message => {
    const lane = LANE_BY_CCIP_SELECTOR.get(message.sourceSelector);
    const source = lane ? laneWho(lane) : `<span class="mono">${message.sourceSelector}</span>`;
    const recipient = message.recipient
      ? lane ? alink(lane, message.recipient) : `<span class="mono">${short(message.recipient)}</span>` : '—';
    const requested = message.amount == null ? '<div class="m">Malformed</div><div class="s">payload &lt; 52 bytes</div>'
      : `<div class="m">${fmtAmt(message.amount)} requested</div><div class="s">${message.tokens.length} token ${message.tokens.length === 1 ? 'entry' : 'entries'}</div>`;
    const state = message.state === 'active' ? chip('warn', 'Stored on L1', 'retry / recover')
      : message.state === 'retried' ? chip('ok', 'Retry sent', 'L1 cleared')
      : message.state === 'recovered' ? chip('warn', 'Tokens recovered', 'off Shuttle')
      : chip('crit', 'Unknown', 'hash = 0; no event');
    return `<tr>
      <td><span class="num"><div class="m">${ago(message.timestamp)}</div><div class="s">${message.timestamp ? new Date(message.timestamp * 1000).toLocaleString() : 'time unavailable'}</div></span></td>
      <td>${source}</td>
      <td><span class="num">${requested}</span></td>
      <td>${recipient}</td>
      <td>${state}</td>
      <td><span class="who">
        <a class="mono" href="https://ccip.chain.link/msg/${message.messageId}" target="_blank" title="${message.messageId}">CCIP ↗</a>
        <a class="mono" href="${L1.explorer}/tx/${message.tx}" target="_blank" title="${message.tx}">Failure ↗</a>
        ${message.lifecycle ? `<a class="mono" href="${L1.explorer}/tx/${message.lifecycle.tx}" target="_blank" title="${message.lifecycle.tx}">${message.lifecycle.kind === 'retried' ? 'Retry' : 'Recovery'} ↗</a>` : ''}
      </span></td>
    </tr>`;
  }).join('');
  const summary = messages.length
    ? `${active.length} active · ${retried.length} retry sent · ${recovered.length} tokens recovered`
    : 'No failures since 1 Aug 2026.';
  document.getElementById('shuttle').innerHTML = `<div class="card">
    <div class="card-head">
      <h3>L1 receiver failures</h3>
      <span class="desc">${summary}${messages.length ? ' · since 1 Aug 2026' : ''}</span>
      ${viewRefresh('shuttle', 'Shuttle failures')}
    </div>
    ${unknown.length ? `<div class="err-banner">✕ ${unknown.length} message ${unknown.length === 1 ? 'has' : 'have'} no lifecycle event</div>` : ''}
    ${rows ? `<div class="scroll-x"><table>
      <tr><th>Failed</th><th>Source</th><th>Payload</th><th>Recipient</th><th>Current state</th><th>Evidence</th></tr>
      ${rows}</table></div>` : ''}
  </div>`;
}

async function refreshShuttles() {
  try { renderShuttles(await failedMessageData(), null); }
  catch (e) { renderShuttles([], e.message); }
}

// ── Render ───────────────────────────────────────────────────────────────────
// ── Automation ───────────────────────────────────────────────────────────────
// Three planes, three verdicts, deliberately never merged into one light: the registry read ACTIVE
// throughout the 2026-08-13 → 08-16 window in which the author gate rejected every report. A lane is
// only as good as its weakest plane, and registration never carries that verdict on its own.
const AUTOMATION_CACHE_KEY = 'direct-staking-watch.automation-cache';
// How long a lane may sit DUE before "waiting for the next tick" becomes "stalled". This is DERIVED
// from the schedules the workflow actually runs, not fixed: the consolidation moved every lane from a
// 5-minute cron to one hourly cron, and a 30-minute window against an hourly tick would raise a
// critical on essentially every healthy sync — a lane goes due at `lastExecution + delay`, which has no
// relation to its minute-of-hour slot, so a normal wait is up to a full period.
//
// Floor and slack are deliberate: never tighter than the old 30 minutes, and always a quarter-hour
// beyond one full tick period, so RPC lag or a skipped tick is late rather than "undelivered".
const DUE_GRACE_FLOOR_S = 1800;
const DUE_GRACE_SLACK_S = 900;
function dueGraceSeconds(lanes) {
  const periods = (Array.isArray(lanes) ? lanes : []).map(l => cdCron(l?.schedule).periodSec);
  // An unreadable schedule must widen the window, never narrow it: a day is the longest period this
  // page can gloss, and reporting "stalled" off a cron nobody parsed would be a verdict with no basis.
  if (!periods.length || periods.some(p => p == null)) return Math.max(DUE_GRACE_FLOOR_S, 86400 + DUE_GRACE_SLACK_S);
  return Math.max(DUE_GRACE_FLOOR_S, Math.max(...periods) + DUE_GRACE_SLACK_S);
}
// A cached `wei` is fed to BigInt() by the renderer and localStorage is persistent, attacker-adjacent
// input: anything but a plain decimal string — or the `null` that means "read, no Sync log" — would
// throw mid-render and strand the tab. Downgrade an implausible one to "unread", a claim the next
// refresh re-reads, rather than trusting it or dropping the row that carries it. A row that never
// carried an amount (any event but a sync) is left exactly as it is.
const sanitizeWei = e => !('wei' in e) || e.wei === null || (typeof e.wei === 'string' && /^\d+$/.test(e.wei))
  ? e : { ...e, wei: undefined, amtUnread: true };
const automation = { regs: null, regError: null, lanes: null, logs: readAutomationCache(), logErrors: [] };

// The cache is persistent attacker-adjacent input: validate its SHAPE, not just that it parsed. A row
// whose topic is not in EVT would throw inside renderAutomation and strand the tab on its loader
// across every reload until localStorage is cleared by hand.
function readAutomationCache() {
  try {
    const cache = JSON.parse(localStorage.getItem(AUTOMATION_CACHE_KEY));
    if (!cache || typeof cache !== 'object') return {};
    return Object.fromEntries(Object.entries(cache)
      .filter(([name, rows]) => LANES.some(L => L.name === name) && Array.isArray(rows))
      .map(([name, rows]) => [name, rows.filter(e => e && EVT[e.topic] && Array.isArray(e.topics)).map(sanitizeWei)]));
  } catch { return {}; }
}
function saveAutomationCache() {
  try { localStorage.setItem(AUTOMATION_CACHE_KEY, JSON.stringify(automation.logs)); } catch {}
}

// Which registration governs THIS lane: the one consolidated record, which stands for all four. The
// superseded per-lane records are deliberately NOT consulted — a lane is reported against the layout
// that is meant to drive it, and a retired record standing in for it would read as a working lane.
const laneWorkflow = regs => findConsolidated(regs);

const acctFor = (regs, addr) => (regs ?? []).find(a => addr && a.owner.toLowerCase() === addr.toLowerCase()) ?? null;
const execEvents = name => (automation.logs[name] ?? []).filter(e => e.topic === EXEC_TOPIC);

// The six conjuncts of the author gate. Each is one atomic claim; the composite is their conjunction,
// governed by the weakest link — never an average, never the best of them.
function gateChecks(L, d, regs) {
  const eq = (a, b) => !!a && !!b && a.toLowerCase() === b.toLowerCase();
  const read = regsUsable(regs);
  const author = d.creAuthor;
  const wf = laneWorkflow(regs);
  const linked = acctFor(regs, author)?.linked;
  const cell = (key, sub, chain, verdict, a) => ({ key, sub, chain, ...verdict, a: a ? a.toLowerCase() : null });
  return [
    cell('owner link-registered', 'isOwnerLinked(author)', 'L1',
      linked == null ? { level: 'warn', value: 'unread' }
        : linked ? { level: 'ok', value: 'linked' } : { level: 'crit', value: 'NOT linked' }, author),
    cell('registry owner = author', 'workflow.owner ↔ getExpectedAuthor()', 'L1↔L2',
      !read ? { level: 'warn', value: 'unread' }
        : !wf ? { level: 'crit', value: 'no workflow' }
        : eq(wf.t[WF.owner], author) ? { level: 'ok', value: holder(author) }
        : { level: 'crit', value: holder(wf.t[WF.owner]) }, wf ? wf.t[WF.owner] : null),
    cell('forwarder accepted', 'CREReceiver.getForwarder()', 'L2',
      eq(d.creForwarderActual, L.creForwarder) ? { level: 'ok', value: holder(L.creForwarder, 'CRE Forwarder') }
        : { level: 'crit', value: holder(d.creForwarderActual) }, d.creForwarderActual),
    cell('triggerSync allow-listed', 'isCallAllowed()', 'L2',
      d.callAllowed ? { level: 'ok', value: 'allowed' } : { level: 'crit', value: 'blocked' }, null),
    cell('trigger accepts receiver', 'SyncTrigger.getForwarder()', 'L2',
      eq(d.stForwarder, L.creReceiver) ? { level: 'ok', value: holder(L.creReceiver, 'CREReceiver') }
        : { level: 'crit', value: holder(d.stForwarder) }, d.stForwarder),
    cell('SYNC_ROLE held', 'CustomSender.hasRole()', 'L2',
      d.triggerHasRole ? { level: 'ok', value: 'held' } : { level: 'crit', value: 'revoked' }, L.syncTrigger),
  ];
}

// Registration is a RECORD. It warrants "the DON should run this" and nothing about acceptance or delivery.
function registrationChecks(L, regs) {
  if (!regsUsable(regs)) return { level: 'warn', rows: null, unread: true };
  const wf = laneWorkflow(regs);
  if (!wf) return { level: 'crit', rows: null, unread: false };
  const t = wf.t;
  const status = t[WF.status] === 0n ? { level: 'ok', value: 'ACTIVE' }
    : { level: 'crit', value: t[WF.status] === 1n ? 'PAUSED' : `status ${t[WF.status]}` };
  const don = t[WF.donFamily] === DON_FAMILY ? { level: 'ok', value: t[WF.donFamily] }
    : { level: 'crit', value: esc(t[WF.donFamily]) || '—' };
  // The tag is what `cre workflow deploy` registered; a tag that stops matching the name means the
  // registration no longer describes the lane it is named for.
  const tag = t[WF.tag] === t[WF.name] ? { level: 'ok', value: 'tag = name' }
    : { level: 'crit', value: 'tag ≠ name', sub: esc(t[WF.tag]) || '(empty)' };
  return { level: worst([status.level, don.level, tag.level]), rows: { t, status, don, tag } };
}

// Absence of a delivery is NOT failure: the workflow signs only when a sync is due. Only the
// conjunction "due AND executable AND nothing landed" is a real stall.
//
// The idle state is named IDLE, never "delivering". A lane whose last report is weeks old is not
// delivering anything — it has nothing to deliver, which is a different claim, and collapsing the two
// would smuggle liveness back in through a label after the card structure took it out.
function deliveryState(L, d, graceS) {
  const execs = execEvents(L.name);
  const last = execs.length ? execs[0].ts : null;
  const now = Math.floor(Date.now() / 1000);
  // Missing history is checked FIRST: with no logs there is no delivery evidence either way, and a
  // "nothing landed" verdict read off an unfetched history is absence-of-evidence dressed as evidence.
  if (!Array.isArray(automation.logs[L.name]))
    return { level: 'warn', label: 'UNKNOWN', n: null, last: null, note: 'delivery history not loaded' };
  if (d.shouldSync == null || d.canSync == null)
    return { level: 'warn', label: 'UNKNOWN', n: execs.length, last, note: 'sync predicates unreadable' };
  if (d.shouldSync > 0n && !d.canSync)
    return { level: 'warn', label: 'DUE, BLOCKED', n: execs.length, last,
      note: 'blocked on-chain, not by the DON — see Overview' };
  // The grace window runs from the moment the lane BECAME due (lastExecution + delay), never from the
  // last delivery: shouldSyncAmount() only goes non-zero once the 12h delay has elapsed, so measuring
  // staleness against the last report would make every normal sync window fire this critical.
  const dueSince = d.lastExec != null && d.delay != null ? Number(d.lastExec + d.delay) : null;
  const overdue = dueSince != null && now - dueSince > graceS;
  if (d.shouldSync > 0n && d.canSync && overdue)
    return { level: 'crit', label: 'DUE, UNDELIVERED', n: execs.length, last,
      note: `${fmtEth(d.shouldSync, 2)} WETH due for ${ago(dueSince).replace(' ago', '')} — past the ${
        Math.round(graceS / 60)} min this cadence allows, no report` };
  if (d.shouldSync > 0n)
    return { level: 'ok', label: 'DUE', n: execs.length, last, note: 'awaiting the next DON tick' };
  if (!execs.length)
    return { level: 'warn', label: 'NEVER DELIVERED', n: 0, last, note: 'no accepted report' };
  return { level: 'ok', label: 'IDLE', n: execs.length, last, note: 'nothing due' };
}

// One event's human reading, from indexed topics only — Linea's explorer decodes nothing for us.
// Every field is READ from the log, never assumed: this is the card that has to stay truthful when
// someone with the owner key allow-lists a call that is not triggerSync().
const SELECTORS = { [TRIGGER_SYNC_SEL]: 'triggerSync()' };
const selName = t => {
  if (!t) return '<span class="chip crit">unreadable selector</span>';
  const sel = '0x' + t.slice(2, 10);
  return SELECTORS[sel] ?? `<span class="chip crit">unknown call ${sel}</span>`;
};
function eventDetail(e) {
  const addr = t => t ? '0x' + t.slice(-40) : null;
  // holder() resolves the name from the ADDRESS via NAMES; an unrecognised target stays a short hex
  // string rather than borrowing a label it did not earn.
  if (e.topic === EXEC_TOPIC) {
    const call = `${selName(e.topics[2])} on ${holder(addr(e.topics[1]))}`;
    // A sync's size is part of what the row reports, so an unread or absent amount is SAID, not blank.
    if (typeof e.wei === 'string') return `${call} · <strong>${fmtEth(BigInt(e.wei))} WETH</strong>`;
    if (e.wei === null) return `${call} · <span class="chip warn"><div class="m">⚠ no Sync event</div></span>`;
    if (e.amtUnread) return `${call} · <span style="color:var(--muted)">amount unread</span>`;
    return call;
  }
  if (e.topic === '0xb35b8e3487df8622d32523c450283db1844a7a279925f30df21d27bc116189d7')
    return `${selName(e.topics[2])} on ${holder(addr(e.topics[1]))} → ${decBool(e.data) ? 'allowed' : 'blocked'}`;
  if (e.topic === '0x94b2de810873337ed265c5f8cf98c9cffefa06b8607f9a2f1fbaebdfbcfbef1c')
    return `${e.data && e.data !== '0x' ? fmtEth(decU(e.data)) : '—'} ETH → ${holder(addr(e.topics[1]))}`;
  return `${holder(addr(e.topics[1]))} → ${holder(addr(e.topics[2]))}`;
}

function renderAutomation() {
  const lanes = automation.lanes;
  if (!lanes) return; // the log fetch alone cannot draw the planes; first paint comes from refresh()
  const regs = automation.regs;

  // Resolved before anything renders, because the delivery verdict depends on it: the chain's published
  // params if the record carries them, this repo's copy otherwise. Both the grace window below and the
  // Deployed Parameters card read this one answer, so they cannot disagree about which cadence is live.
  const cons = findConsolidated(regs);
  const attrsHex = cons ? cons.t[WF.attributes] : null;
  const attrs = parseAttributes(attrsHex);
  regAttest = attrs.kind === 'attest' ? attrs.a : null;   // what the artifact checker verifies against
  const repoParams = (() => { try { return JSON.parse(CRE_CONFIG_JSON); } catch { return null; } })();
  // Only the verbatim-config payload puts parameters on the chain; under an attestation the table is
  // this repo's copy, vouched for by a digest. Three states, not two, and the label says which.
  const paramsSrc = (attrs.kind === 'config' ? attrs.config : null) ?? repoParams;
  const paramsOrigin = attrs.kind === 'config' ? 'chain'
    : (attrs.kind === 'attest' && attrs.a.config === creConfigSha) ? 'attested' : 'repo';
  const paramsFromChain = paramsOrigin === 'chain';
  const graceS = dueGraceSeconds(paramsSrc?.lanes);

  const perLane = lanes.map(l => l.error ? null : ({
    L: l.L, d: l.d,
    reg: registrationChecks(l.L, regs),
    gate: gateChecks(l.L, l.d, regs),
    del: deliveryState(l.L, l.d, graceS),
  }));
  const armed = perLane.filter(p => p && p.gate.every(c => c.level === 'ok'));
  const active = perLane.filter(p => p && p.reg.rows && p.reg.rows.status.level === 'ok');
  const lastDelivery = perLane.reduce((m, p) => Math.max(m, p?.del.last ?? 0), 0) || null;
  const regsRead = regsUsable(regs);
  // "unread" is not a count and "never" is not "not fetched" — each tile states which it is.
  const deliveryRead = LANES.every(L => Array.isArray(automation.logs[L.name])) && !automation.logErrors.length;
  // Name the conjunct that actually blocks, rather than assuming the reason.
  const gateBlocked = [...new Set(perLane.filter(Boolean)
    .map(p => p.gate.find(c => c.level === 'crit')?.key).filter(Boolean))];

  // ── Card A2 — the parameters the registered workflow runs on ──
  // Source order is deliberate: whatever the RECORD publishes wins over this repo's copy, because the
  // question is what is deployed, not what is declared here. The repo copy is the fallback, and it is
  // labelled as such — a lane table with no chain backing must never read like a chain reading.

  // Row 1 — is there a record at all. "Not registered yet" is the EXPECTED state until the Safe executes
  // the upsert, so it is stated as a fact and kept out of the tab's status: an unstarted step is not a fault.
  const recRow = !regsUsable(regs)
    ? { level: 'warn', html: chip('warn', 'registry unread', 'L1 read failed — record state unknown'), count: true }
    : !cons
      ? { level: 'ok', html: chip('', 'not registered yet', `no workflow named ${esc(CRE_WORKFLOW_NAME)} under ${who(CRE_WF_OWNER)}`), count: false }
      : { level: cons.t[WF.status] === 0n ? 'ok' : 'warn',
          html: chip(cons.t[WF.status] === 0n ? 'ok' : 'warn',
            cons.t[WF.status] === 0n ? 'ACTIVE' : cons.t[WF.status] === 1n ? 'PAUSED' : `status ${cons.t[WF.status]}`,
            `${holder(cons.t[WF.owner])} · registered ${ago(Number(cons.t[WF.createdAt]))}`), count: true };

  // Row 2 — are the params observable on-chain at all, and do they match this page's copy? attributes is
  // arbitrary owner-written bytes the registry never reads, which is exactly what makes it usable for
  // publishing the config verbatim — and exactly why a match is an ATTESTATION, not an oracle.
  const pubRow = !cons ? { level: 'ok', html: chip('', 'n/a', 'nothing registered to publish from'), count: false }
    : attrs.kind === 'empty'
      ? { level: 'warn', html: chip('warn', 'attributes empty', 'nothing about the deployed artifacts was published — the table below is this repo\'s copy, unconfirmed'), count: true }
    : attrs.kind === 'attest'
      // The attestation publishes DIGESTS, so the lane table below stays the repo's copy — but a copy
      // whose sha256 the record commits to is a different thing from an unchecked one, and the verdict
      // says which of the two you are looking at.
      ? (attrs.a.config === creConfigSha
          ? { level: 'ok', html: chip('ok', 'matches repo', 'config.deploy.json'), count: true }
          : { level: 'crit', html: chip('crit', 'does not match repo', `<span class="mono">${esc(String(attrs.a.config ?? '—').slice(0, 16))}…</span> ≠ <span class="mono">${creConfigSha.slice(0, 16)}…</span>`), count: true })
    : attrs.kind === 'config'
      ? (a => ({ level: a.level, html: chip(a.level, a.label, a.note + (a.level === 'ok' ? '' : ' — the table below shows the CHAIN\'s')), count: true }))(
          paramsAgreement(attrsHex, attrs.config, CRE_CONFIG_JSON, repoParams))
    : { level: 'crit', html: chip('crit', 'unrecognised payload', `${attrs.bytes} bytes that are neither an attestation nor a config`), count: true };

  // Row 3 — the page's own integrity. Recomputed here so a wrong constant cannot masquerade as agreement.
  const digRow = !SHA256_OK
    ? { level: 'crit', html: chip('crit', 'digest engine failed self-test', 'no digest on this page can be trusted'), count: true }
    : creConfigSha === CRE_CONFIG_SHA256
      ? { level: 'ok', html: chip('ok', 'matches pin', `<span class="mono">${CRE_CONFIG_SHA256.slice(0, 16)}…</span>`), count: true }
      : { level: 'crit', html: chip('crit', 'sha256 ≠ pin', `computed <span class="mono">${esc(creConfigSha.slice(0, 16))}…</span> — regenerate with just cre-workflow-hash`), count: true };

  // Row 3b — the source and binary the record attests to. Only the attestation can answer this: the
  // config alone never said WHICH code was uploaded, and the artifact store answers 403 to everyone.
  const srcRow = !cons || attrs.kind !== 'attest'
    ? { level: 'ok', html: chip('', 'not attested', 'no source digest is published for this record'), count: false }
    : (() => {
        const srcOk = attrs.a.source === CRE_DEPLOYED_SOURCE_SHA256;
        return { level: srcOk ? 'ok' : 'crit', count: true, html: chip(srcOk ? 'ok' : 'crit',
          srcOk ? 'matches deployment' : 'does not match deployment',
          srcOk ? 'main.ts · 9dd7005'
            : `<span class="mono">${esc(String(attrs.a.source ?? '—').slice(0, 16))}…</span> ≠ <span class="mono">${CRE_DEPLOYED_SOURCE_SHA256.slice(0, 16)}…</span>`) };
      })();

  // Row 4 — the addresses the params point at. A config that is internally valid but aims at the wrong
  // receiver would still register, still run, and never deliver: worth its own row, not a footnote.
  const addrOk = (a, b) => !!a && !!b && a.toLowerCase() === b.toLowerCase();
  const tgtRow = !paramsSrc ? { level: 'crit', html: chip('crit', 'params unparseable', 'neither chain nor repo yielded a config'), count: true }
    : addrOk(paramsSrc.receiverAddress, COMMON_DEPLOYED.creReceiver) && addrOk(paramsSrc.targetAddress, COMMON_DEPLOYED.syncTrigger)
      ? { level: 'ok', html: chip('ok', 'addresses match', `${short(COMMON_DEPLOYED.creReceiver)} → ${short(COMMON_DEPLOYED.syncTrigger)}`), count: true }
      : { level: 'crit', html: chip('crit', 'addresses off-pin',
          `receiver <span class="mono">${esc(short(paramsSrc.receiverAddress))}</span> · target <span class="mono">${esc(short(paramsSrc.targetAddress))}</span>`), count: true };

  // Same renderer the calldata explainer uses, so a lane table cannot say one thing before signing and
  // another after: one implementation, one set of issues.
  const laneTab = laneTableHtml(paramsSrc?.lanes);
  const paramsLevel = worst([recRow, pubRow, digRow, srcRow, tgtRow].filter(r => r.count).map(r => r.level)
    .concat(cons ? laneTab.issues.map(i => i.level) : []));

  const paramsCard = `<div class="card">
    <div class="card-head">
      <h3>Deployed Parameters</h3>
      <span class="desc">Digests show what was declared, not what the DON runs.</span>
    </div>
    <div class="params-checks">
      <div class="params-check"><div class="params-check-label">Registration</div>${recRow.html}</div>
      <div class="params-check"><div class="params-check-label">Config</div>${pubRow.html}</div>
      <div class="params-check"><div class="params-check-label">Source</div>${srcRow.html}</div>
      <div class="params-check"><div class="params-check-label">Config hash</div>${digRow.html}</div>
      <div class="params-check"><div class="params-check-label">Contracts</div>${tgtRow.html}</div>
    </div>
    <div class="card-head"><span class="desc">Lane triggers · <strong>${
      paramsOrigin === 'chain' ? 'on-chain config'
      : paramsOrigin === 'attested' ? 'attested repo config'
      : 'unverified repo config'}</strong> ·
      gas <span class="mono">${esc(paramsSrc?.writeGasLimit ?? '—')}</span></span></div>
    ${laneTab.html}
    ${laneTab.issues.map(i => `<div class="err-banner">${i.level === 'crit' ? '✕' : '⚠'} ${i.text}${
      i.level === 'crit' && laneTab.missing.length ? ` — ${paramsFromChain ? 'the registered config drives fewer lanes than this dashboard tracks' : 'the repo config is short a lane'}` : ''}</div>`).join('')}
  </div>`;

  const level = worst([
    paramsLevel,
    ...(automation.regError ? ['crit'] : []),
    ...lanes.filter(l => l.error).map(() => 'crit'),
    // An event-source outage means the delivery plane is unverified; a green tab must not be read off a
    // cache that could not be refreshed.
    ...(automation.logErrors.length ? ['warn'] : []),
    ...perLane.filter(Boolean).flatMap(p => [p.reg.level, p.del.level, ...p.gate.map(c => c.level)]),
  ]);
  setTabStatus('automation', level === 'ok' ? null : level);

  const hero = `<div class="card hero">
    <div>
      <h2 class="serif">CRE automation</h2>
      <p>Registry, author gate, and delivery by lane.</p>
      ${viewRefresh('automation', 'Automation')}
    </div>
    <div class="stat">
      <!-- LANES, not workflows: under the consolidated layout there is ONE registration behind all four
           of these, so a tile headed "Workflows ACTIVE" would read as a count of records and be wrong. -->
      <div class="k">Lanes registered</div>
      <div class="v serif">${regsRead ? `${active.length}<span style="color:var(--muted)">/${LANES.length}</span>`
        : '<span style="color:var(--muted)">?</span>'}</div>
      <div class="s">${!regsRead ? 'registry unread — count unknown'
        : `DON ${DON_FAMILY} · ${cons ? 'one record, four lanes' : 'no record governs a lane'}`}</div>
    </div>
    <div class="stat ${gateBlocked.length ? 'critical' : 'tinted'}">
      <div class="k">Author gate armed</div>
      <div class="v serif">${armed.length}<span style="color:var(--muted)">/${LANES.length}</span></div>
      <div class="s">${armed.length === LANES.length ? 'reports accepted'
        : gateBlocked.length ? 'blocked at: ' + esc(gateBlocked.join(', '))
        : 'gate state unverified — see the lane table'}</div>
    </div>
    <div class="stat tinted">
      <div class="k">Last delivery</div>
      <div class="v serif">${deliveryRead
        ? (lastDelivery ? ago(lastDelivery) : 'never')
        : '<span style="color:var(--muted)">unread</span>'}</div>
      <div class="s">${deliveryRead ? 'reports run only when sync is due'
        : 'event source unreachable — delivery history not verified'}</div>
    </div>
  </div>`;

  const laneRows = perLane.map((p, i) => {
    if (!p) return `<tr><td>${laneWho(lanes[i].L)}</td><td colspan="4">${chip('crit', 'RPC error', lanes[i].error)}</td></tr>`;
    const regBad = p.reg.rows
      ? [p.reg.rows.status, p.reg.rows.don, p.reg.rows.tag].find(c => c.level !== 'ok')
      : null;
    const registration = !p.reg.rows
      ? (p.reg.unread ? chip('warn', 'UNKNOWN', 'registry unread') : chip('crit', 'MISSING', 'workflow not registered'))
      : regBad ? chip(regBad.level, 'MISCONFIGURED', regBad.value)
      : chip('ok', 'ACTIVE', `<span class="mono">${esc(CRE_WORKFLOW_NAME)}</span> · one record, four lanes`);
    const gateBad = p.gate.find(c => c.level !== 'ok');
    const gate = gateBad
      ? chip(gateBad.level, gateBad.level === 'crit' ? 'BLOCKED' : 'UNKNOWN', gateBad.key)
      : chip('ok', 'ARMED');
    return `<tr>
      <td>${laneWho(p.L)}</td>
      <td>${registration}</td>
      <td>${gate}</td>
      <td>${chip(p.del.level, p.del.label, p.del.note)}</td>
      <td><span class="num"><div class="m">${p.del.last ? ago(p.del.last) : '—'}</div>
          <div class="s">${p.del.last ? new Date(p.del.last * 1000).toLocaleString() : 'no accepted report'}</div></span></td>
    </tr>`;
  }).join('');

  const laneCard = `<div class="card">
    <div class="card-head">
      <h3>Automation by lane</h3>
      ${legendHtml()}
    </div>
    ${automation.regError ? `<div class="err-banner">✕ registry unreadable: ${automation.regError}</div>` : ''}
    ${automation.logErrors.length ? `<div class="err-banner">⚠ event source unreachable: ${automation.logErrors.join(', ')} · showing cached history<button class="retry" onclick="this.disabled=true;refreshAutomationLogs()">⟳ retry</button></div>` : ''}
    <div class="scroll-x"><table class="syncm">
      <tr><th>Lane</th><th>Workflow</th><th>Author gate</th><th>Delivery</th><th>Last accepted report</th></tr>
      ${laneRows}
    </table></div>
  </div>`;

  // Recent control-plane history.
  const events = LANES.flatMap(L => (automation.logs[L.name] ?? []).map(e => ({ L, ...e })))
    .sort((a, b) => (b.ts ?? 0) - (a.ts ?? 0));
  const visibleEvents = events.slice(0, 12);
  const evRows = visibleEvents.map(e => `<tr>
    <td><span class="num"><div class="m">${ago(e.ts)}</div>
        <div class="s">${e.ts ? new Date(e.ts * 1000).toLocaleString() : 'block ' + e.block}</div></span></td>
    <td><span class="who"><span class="avatar">${netLogo(e.L)}</span><span class="name">${e.L.name}</span></span></td>
    <td><span class="tag ${EVT[e.topic].kind === 'exec' ? 'sync' : ''}">${EVT[e.topic].label}</span></td>
    <td>${eventDetail(e)}</td>
    <td><a href="${e.L.explorer}/tx/${e.tx}" target="_blank" title="${e.tx}" class="mono">${short(e.tx)}&thinsp;↗</a></td>
  </tr>`).join('');
  const missingLanes = LANES.filter(L => !Array.isArray(automation.logs[L.name])).map(L => L.name);
  const evCard = `<div class="card">
    <div class="card-head">
      <h3>Recent events</h3>
      <span class="desc">Latest ${visibleEvents.length} events.</span>
    </div>
    ${automation.logErrors.length || missingLanes.length ? `<div class="err-banner">⚠ incomplete: ${
      [...automation.logErrors, ...missingLanes.map(n => n + ' (not loaded)')].join(', ')} — rows below are cached or partial</div>` : ''}
    ${evRows ? `<div class="scroll-x"><table>
      <tr><th>Age</th><th>Lane</th><th>Event</th><th>Detail</th><th>Tx</th></tr>${evRows}</table></div>`
      : '<div class="err-banner">no CREReceiver events found</div>'}
  </div>`;

  document.getElementById('automation-cards').innerHTML = hero + laneCard + paramsCard + evCard;
}

function render(l1, lanes) {
  const laneOverviewLevels = lanes.map(l => l.error
    ? 'crit'
    : worst([syncState(l.d)[0], floatState(l.d).level]));

  const overviewLevel = worst([
    l1.error ? 'crit' : worst(l1BalanceChecks(l1.d).map(c => c.level)),
    ...laneOverviewLevels,
  ]);
  const accessLevel = worst([
    l1.error ? 'crit' : worst(l1AccessChecks(l1.d).map(c => c.level)),
    ...lanes.map(l => l.error ? 'crit' : worst(laneChecks(l.L, l.d).map(c => c.level))),
  ]);
  setTabStatus('main', overviewLevel === 'ok' ? null : overviewLevel);
  setTabStatus('access', accessLevel === 'ok' ? null : accessLevel);

  const rpcOk = [l1, ...lanes].filter(x => !x.error).length;
  document.getElementById('rpcstat').innerHTML =
    `<span class="dot ${rpcOk === 5 ? 'ok' : 'crit'}"></span> RPC ${rpcOk}/5`;

  // hero numbers
  const live = lanes.filter(l => !l.error);
  const crits = laneOverviewLevels.filter(level => level === 'crit').length;
  const warns = laneOverviewLevels.filter(level => level === 'warn').length;
  const healthy = LANES.length - crits;
  const totalWeth = live.reduce((s, l) => s + (l.d.poolWeth ?? 0n), 0n);
  const synced = syncVolumeStatus();

  const hero = `<div class="card hero">
    <div>
      <h2 class="serif">Sync &amp; custody</h2>
      <p>WETH accumulates on L2 and syncs to L1 for staking.</p>
      ${viewRefresh('main', 'Overview')}
    </div>
    <div class="stat">
      <div class="k">Lanes healthy</div>
      <div class="v serif">${healthy}<span style="color:var(--muted)">/${LANES.length}</span></div>
      <div class="s">${crits ? crits + ' critical' : 'no critical lanes'}${warns ? ' · ' + warns + ' warn' : ''}</div>
    </div>
    <div class="stat tinted">
      <div class="k">Pool WETH</div>
      <div class="v serif">${fmtEth(totalWeth, 2)} <span class="unit">WETH</span></div>
      <div class="s">across 4 lanes</div>
    </div>
    <div class="stat ${synced.level}" id="sync-volume">
      <div class="k" title="Cumulative amount emitted by CustomSender.Sync across all lanes">Synced to L1</div>
      <div class="v serif${synced.loading ? ' loading' : ''}" role="status" aria-live="polite" aria-busy="${!!synced.loading || synced.refreshing}">${syncVolumeValue(synced)}</div>
      <div class="s sync-volume-sub"><span class="sync-volume-text">${synced.sub}</span><span class="spin" aria-hidden="true"${synced.refreshing ? '' : ' hidden'}></span></div>
    </div>
  </div>`;

  // sync matrix
  const num = (m, s) => `<span class="num"><div class="m">${m}</div><div class="s">${s}</div></span>`;
  const syncRows = lanes.map(l => {
    if (l.error) return `<tr><td>${laneWho(l.L)}</td><td colspan="4"><span class="chip crit"><div class="m">✕ RPC error</div><div class="s">${l.error}</div></span></td></tr>`;
    const d = l.d, [slv, sm, ss] = syncState(d), f = floatState(d);
    return `<tr>
      <td>${laneWho(l.L)}</td>
      <td>${chip(slv, sm, slv === 'ok' ? 'last sync ' + ago(d.lastExec) : ss)}</td>
      <td>${num(fmtEth(d.poolWeth, 2) + ' WETH', d.minAmount != null ? `min ${fmtEth(d.minAmount, 0)} · max ${fmtEth(d.maxAmount, 0)}` : '—')}</td>
      <td>${num(fmtEth(d.poolWsteth, 2) + ' wstETH', 'fastStake liquidity')}</td>
      <td>${chip(f.level, f.x != null ? f.x.toFixed(2) + '× maxFees' : '—', fmtEth(d.float) + ' ETH on trigger')}</td>
    </tr>`;
  }).join('');

  const syncCard = `<div class="card">
    <div class="card-head">
      <h3>Sync Matrix</h3>
      ${legendHtml()}
    </div>
    <div class="scroll-x"><table class="syncm">
      <tr><th>Lane</th><th>Sync state</th><th>Pool WETH</th><th>Pool wstETH</th><th title="ok ≥ 1.5× · warn ≥ 1× · critical &lt; 1×">Fee float</th></tr>
      ${syncRows}
    </table></div>
  </div>`;

  // ownership matrix: rows = checks grouped by contract, columns = lanes.
  // These are tripwires, not daily reads — deviations surface on top, the green wall folds away.
  const perLane = lanes.map(l => l.error ? null : laneGroups(l.L, l.d));
  const okLane = lanes.find(l => !l.error);
  const template = laneGroups(okLane?.L ?? LANES[0], okLane?.d ?? {});
  const laneAddrs = lanes.map(l => laneGroups(l.L, {}).map(g => g.addr));

  const checkRow = (gi, ci, row) => `<tr>
    <td class="rowlabel">${row.key}<span class="sub mono">${row.sub}</span></td>
    ${perLane.map((cs, li) => {
      if (!cs) return '<td>—</td>';
      const c = cs[gi].checks[ci];
      const inner = chip(c.level, c.value, c.a ? `<span class="mono">${short(c.a)}&thinsp;↗</span>` : null);
      return `<td>${c.a ? `<a class="chiplink" href="${lanes[li].L.explorer}/address/${c.a}" target="_blank" title="${c.a}">${inner}</a>` : inner}</td>`;
    }).join('')}
  </tr>`;
  const buildTable = filter => `<table class="ownm">
    <tr><th>Check</th>${lanes.map(l => `<th>${netName(l.L)}</th>`).join('')}</tr>
    ${template.map((g, gi) => {
      const rows = g.checks.map((row, ci) => ({ row, ci })).filter(({ ci }) => filter(gi, ci));
      if (!rows.length) return '';
      return `<tr class="group"><td class="gname">${g.contract}</td>` +
        lanes.map((l, li) => `<td><a href="${l.L.explorer}/address/${laneAddrs[li][gi]}" target="_blank" title="${laneAddrs[li][gi]}">${short(laneAddrs[li][gi])}&thinsp;↗</a></td>`).join('') +
        '</tr>' + rows.map(({ row, ci }) => checkRow(gi, ci, row)).join('');
    }).join('')}
  </table>`;

  const deviates = (gi, ci) => perLane.some(cs => cs && cs[gi].checks[ci].level !== 'ok');
  const nDev = template.flatMap((g, gi) => g.checks.filter((_, ci) => deviates(gi, ci))).length;
  const nChecks = template.reduce((s, g) => s + g.checks.length, 0);
  const unreachable = lanes.filter(l => l.error).map(l => l.L.name);
  const reachNote = unreachable.length ? ` · ${unreachable.join(', ')} unreachable` : '';

  const ownCard = `<div class="card">
    <div class="card-head">
      <h3>Ownership &amp; Wiring</h3><span class="desc">On-chain values vs expected. ${ICO.contract} contract · ${ICO.safe} Safe · ${ICO.eoa} EOA</span>
      ${viewRefresh('access', 'Access Control')}
    </div>
    ${nDev ? `<div class="err-banner">✕ ${nDev} of ${nChecks} checks deviate from target${reachNote}</div>` : ''}
    <div class="scroll-x">${buildTable(() => true)}</div>
  </div>`;

  // L1 cards: balances stay in Overview; roles and ownership live in Access Control.
  const l1Access = l1.error ? [] : l1AccessChecks(l1.d);
  const l1Balances = l1.error ? [] : l1BalanceChecks(l1.d);
  const l1BalanceBody = l1.error
    ? `<div class="err-banner">RPC error: ${l1.error}</div>`
    : `<div class="l1-metric-grid l1-balance-grid">${l1Balances.map(c => `<div class="l1-metric ${c.level}">
        <div class="l1-metric-label">${c.key.replace('Receiver ', '')}</div>
        ${chip(c.level, c.value, c.sub)}
      </div>`).join('')}</div>`;
  const l1BalanceCard = `<div class="card l1-card l1-balance-card">
    <div class="card-head">
      <div class="l1-card-copy">
        <h3>${netName(L1)}</h3>
        <span class="desc">Shared receiver balances</span>
      </div>
      <span class="l1-card-links">${alink(L1, L1.receiver, 'LidoCustomReceiver')} ${alink(L1, L1.proxyAdmin, 'ProxyAdmin')}</span>
    </div>${l1BalanceBody}</div>`;

  const l1AccessBody = l1.error
    ? `<div class="err-banner">RPC error: ${l1.error}</div>`
    : `<div class="l1-metric-grid l1-access-grid">${l1Access.map(c => `<div class="l1-metric ${c.level}">
        <div class="l1-metric-label">${c.key}</div>
        ${chip(c.level, c.value, c.sub)}
      </div>`).join('')}</div>`;
  const l1AccessCard = `<div class="card l1-card">
    <div class="card-head">
      <div class="l1-card-copy">
        <h3>${netName(L1)}</h3>
        <span class="desc">Access control</span>
      </div>
      <span class="l1-card-links">${alink(L1, L1.receiver, 'LidoCustomReceiver')} ${alink(L1, L1.proxyAdmin, 'ProxyAdmin')}</span>
    </div>${l1AccessBody}</div>`;

  document.getElementById('main').innerHTML = hero + syncCard + l1BalanceCard;
  document.getElementById('access').innerHTML = ownCard + l1AccessCard;
}

const legendHtml = () => `<span class="legend">
  <span><span class="dot ok"></span> ok</span>
  <span><span class="dot warn"></span> warn</span>
  <span><span class="dot crit"></span> critical</span></span>`;

const laneWho = L => `<span class="who">
  <span class="avatar">${netLogo(L)}</span>
  <span><span class="name">${L.name}</span><br>
  <span class="sub">${alink(L, L.syncTrigger, 'trigger')} · ${alink(L, L.pool, 'pool')}</span></span></span>`;

// ── Lane triggers: the crons and networks a config actually registers ────────
// One workflow, four cron triggers, and the only place they exist is the config — which the registry
// stores as a 403-gated URL. Wherever a copy of that config IS available (published in `attributes`, or
// this page's own pinned copy), it is worth reading properly rather than echoing: a six-field CRE cron
// misread as five-field crontab, a duplicated selector, or two lanes landing in the same minute are all
// silent at registration and only surface as behaviour weeks later.
const laneOfSelector = sel => LANES.find(L => String(sel ?? '') === `ethereum-mainnet-${L.name.toLowerCase()}-1`) ?? null;

// CRE cron carries a SECONDS field first — six fields, not crontab's five. Reading "0 15 * * * *" with
// crontab habits gives a different schedule entirely, which is why the field count is a verdict and not
// a formatting detail.
function cdCron(schedule) {
  const f = String(schedule ?? '').trim().split(/\s+/).filter(Boolean);
  if (f.length === 5) return { level: 'crit', reads: 'five fields — crontab, not CRE', periodSec: null,
    note: 'CRE takes six fields, seconds first; a five-field expression means something else here', next: [] };
  if (f.length !== 6) return { level: 'crit', reads: `${f.length} field${f.length === 1 ? '' : 's'}`, periodSec: null,
    note: 'expected six: sec min hour day month weekday', next: [] };
  const [sec, min, hour, dom, mon, dow] = f;
  const pad = n => String(n).padStart(2, '0');
  const step = spec => (/^\*\/[1-9]\d*$/.test(spec) ? Number(spec.slice(2)) : null);
  const fixed = spec => (/^\d+$/.test(spec) ? Number(spec) : null);
  const known = spec => spec === '*' || fixed(spec) !== null || step(spec) !== null;
  const hits = (spec, v) => spec === '*' || fixed(spec) === v || (step(spec) !== null && v % step(spec) === 0);

  // Only the shapes this system uses are glossed, and the seconds field must be a fixed value — the
  // scan below walks minutes, so a wildcard second would be described by a search that never looked at
  // seconds. Anything else is reported as un-glossed rather than guessed at.
  const s0 = fixed(sec);
  if (s0 === null || ![min, hour].every(known) || dom !== '*' || mon !== '*' || dow !== '*')
    return { level: 'warn', reads: 'pattern not glossed here', periodSec: null,
      note: 'read the six fields directly — this page only spells out the shapes this system uses', next: [] };

  const mStep = step(min), hStep = step(hour), mFix = fixed(min), hFix = fixed(hour);
  const reads =
    hour === '*' && min === '*' ? `every minute at :${pad(s0)}`
    : hour === '*' && mStep ? `every ${mStep} minutes at :${pad(s0)}`
    : hour === '*' && mFix !== null ? `every hour at :${pad(mFix)}:${pad(s0)}`
    : hStep && mFix !== null ? `every ${hStep} hours at :${pad(mFix)}:${pad(s0)}`
    : hFix !== null && mFix !== null ? `once a day at ${pad(hFix)}:${pad(mFix)}:${pad(s0)}`
    : `sec ${sec} · min ${min} · hour ${hour}`;

  // Next fires by scanning forward minute by minute (bounded to 48h), which handles every shape above
  // without a per-shape formula. The PERIOD is then read off the gaps rather than assumed — for a step
  // expression that does not divide the hour, gaps are uneven, so the widest one is the honest answer.
  const now = new Date();
  const next = [];
  let t = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), now.getUTCHours(), now.getUTCMinutes(), s0));
  for (let i = 0; i < 2880 && next.length < 4; i++) {
    if (t > now && hits(hour, t.getUTCHours()) && hits(min, t.getUTCMinutes())) next.push(new Date(t));
    t = new Date(t.getTime() + 60e3);
  }
  const gaps = next.slice(1).map((d, i) => (d - next[i]) / 1000);
  return { level: 'ok', reads, note: null, next: next.slice(0, 2),
    periodSec: gaps.length ? Math.max(...gaps) : null };
}

// Renders the lane table shared by the Deployed Parameters card and the calldata explainer, and returns
// the issues it found so the caller can fold them into its own verdict instead of re-deriving them.
function laneTableHtml(lanes) {
  const list = Array.isArray(lanes) ? lanes : [];
  const issues = [];
  const seen = new Set(), minutes = new Map();
  const rows = list.map((ln, i) => {
    const sel = String(ln?.chainSelectorName ?? '');
    const L = laneOfSelector(sel);
    const c = cdCron(ln?.schedule);
    if (!L) issues.push({ level: 'crit', text: `lane ${i + 1} names ${esc(sel) || 'no chain'} — not one of the four this system runs` });
    if (seen.has(sel)) issues.push({ level: 'crit', text: `${esc(sel)} appears twice — two triggers would write the same report to the same chain` });
    seen.add(sel);
    if (c.level !== 'ok') issues.push({ level: c.level, text: `${esc(sel) || `lane ${i + 1}`}: ${c.reads}` });
    const mm = (c.reads?.match(/^every hour at :(\d\d)/) ?? [])[1];
    if (mm != null) { minutes.set(mm, (minutes.get(mm) ?? 0) + 1); }
    return `<tr>
      <td>${L ? laneWho(L) : chip('crit', 'unknown network', esc(sel) || '(empty)')}</td>
      <td><span class="num"><div class="m mono">${esc(sel) || '—'}</div>
          <div class="s">${L ? `chain ${L.chainId}` : 'no lane on this dashboard'}</div></span></td>
      <td><span class="num"><div class="m mono">${esc(String(ln?.schedule ?? '—'))}</div>
          <div class="s">${c.level === 'ok' ? esc(c.reads) : `<span class="chip ${c.level}"><div class="m">${esc(c.reads)}</div></span>`}</div></span></td>
      <td class="s">${c.next.length
        ? `${c.next.map(d => d.toISOString().replace('T', ' ').slice(0, 19) + 'Z').join('<br>')}`
        : esc(c.note ?? '—')}</td>
    </tr>`;
  }).join('');
  [...minutes].filter(([, n]) => n > 1).forEach(([mm]) =>
    issues.push({ level: 'warn', text: `two lanes both fire at :${mm} — the stagger that keeps executions apart is gone` }));
  const missing = LANES.filter(L => !list.some(ln => laneOfSelector(ln?.chainSelectorName) === L));
  if (list.length && missing.length)
    issues.push({ level: 'crit', text: `no trigger for ${missing.map(L => L.name).join(', ')}` });
  return { issues, missing, html: `<div class="scroll-x"><table class="syncm">
    <tr><th>Network</th><th>Chain selector</th><th>Cron (seconds-first)</th><th>Next fires (UTC)</th></tr>
    ${rows || '<tr><td colspan="4">no lanes in this config</td></tr>'}
  </table></div>` };
}

// ── Calldata explainer — what the multisig is actually about to sign ─────────
// A Safe signer is shown a destination and a hex blob. The blob alone decides what happens, and
// nothing in the path spells out what its fields MEAN here: the CRE CLI prints it without commentary,
// the Safe UI renders bytes, and an explorer at best names the function. So it is decoded in-page and
// every field is given a VERDICT against the same pins the rest of this tab checks — a decoded value
// that nobody compares to anything is how a wrong workflowId or an empty attributes field gets signed.
//
// Local only: no network write, no signature, nothing leaves the page. The one optional read is an
// eth_call against the registry to ask whether a workflowId is already taken.
const REG_FN = {
  '0xb377bfc5': { name: 'upsertWorkflow',
    types: ['string', 'string', 'bytes32', 'uint8', 'string', 'string', 'string', 'bytes', 'bool'],
    args: ['workflowName', 'tag', 'workflowId', 'status', 'donFamily', 'binaryUrl', 'configUrl', 'attributes', 'keepAlive'] },
  '0xdc101969': { name: 'linkOwner', types: ['uint256', 'bytes32', 'bytes'], args: ['validityTimestamp', 'proof', 'signature'] },
  '0x39d68c6a': { name: 'unlinkOwner', types: ['address', 'uint256', 'bytes'], args: ['owner', 'validityTimestamp', 'signature'] },
  '0xe690f332': { name: 'pauseWorkflow', types: ['bytes32'], args: ['workflowId'] },
  '0x530979d6': { name: 'activateWorkflow', types: ['bytes32', 'string'], args: ['workflowId', 'donFamily'] },
  '0x695e1340': { name: 'deleteWorkflow', types: ['bytes32'], args: ['workflowId'] },
  '0xd8b80738': { name: 'batchPauseWorkflows', types: ['bytes32[]'], args: ['workflowIds'] },
  '0xafbb2401': { name: 'updateWorkflowDONFamily', types: ['bytes32', 'string'], args: ['workflowId', 'newDonFamily'] },
};
const SAFE_EXEC_SEL = '0x6a761202';
const SAFE_EXEC = { name: 'execTransaction',
  types: ['address', 'uint256', 'bytes', 'uint8', 'uint256', 'uint256', 'uint256', 'address', 'address', 'bytes'],
  args: ['to', 'value', 'data', 'operation', 'safeTxGas', 'baseGas', 'gasPrice', 'gasToken', 'refundReceiver', 'signatures'] };

// Flat-argument ABI decoder for the shapes above. Deliberately narrow, like decodeTupleArray: it
// returns null on anything it does not recognise rather than guessing, because a half-decoded blob
// rendered as a table is worse than a refusal — it invites a signature on fields nobody verified.
function decodeAbiArgs(hex, types) {
  const b = (hex || '').replace(/^0x/, '');
  if (!b.length || b.length % 64) return null;
  const words = b.length / 64;
  const w = i => b.slice(i * 64, i * 64 + 64);
  const u = i => BigInt('0x' + w(i));
  try {
    return types.map((t, i) => {
      if (i >= words) throw new Error('short');
      if (t === 'bytes32') return '0x' + w(i);
      if (t === 'address') return '0x' + w(i).slice(24);
      if (t === 'bool') return u(i) !== 0n;
      if (t === 'uint8' || t === 'uint256') return u(i);
      const off = Number(u(i));
      if (off % 32) throw new Error('unaligned');
      const at = off / 32;
      if (at < 0 || at >= words) throw new Error('out of range');
      const len = Number(u(at));
      if (t === 'bytes32[]') {
        if (at + 1 + len > words) throw new Error('short array');
        return Array.from({ length: len }, (_, k) => '0x' + w(at + 1 + k));
      }
      const raw = b.slice((at + 1) * 64, (at + 1) * 64 + len * 2);
      if (raw.length < len * 2) throw new Error('short dynamic');
      if (t === 'bytes') return '0x' + raw;
      // Strict UTF-8: registry strings are owner-written, and a lenient decode would render mojibake
      // as if it were a workflow name.
      return new TextDecoder('utf-8', { fatal: true }).decode(bytesOfHex(raw));
    });
  } catch { return null; }
}

// `html: true` marks a value this page composed itself (an icon + label from holder()); everything
// else is escaped on the way out, because most values here are bytes a signer was handed by someone.
const cdRow = (field, value, verdict, note, html, destructive) =>
  ({ field, value, level: verdict, note, html: !!html, destructive: !!destructive });
// A workflowId is only meaningful against the records this tab already read.
const cdKnownWorkflow = id => {
  const regs = automation.regs;
  if (!regsUsable(regs)) return null;
  return regs.flatMap(acct => acct.workflows.map(t => ({ acct, t })))
    .find(({ t }) => (t[WF.id] || '').toLowerCase() === (id || '').toLowerCase()) ?? null;
};

function cdArtifactUrlStatus(value, idBare, expectedLeaf) {
  let u;
  try { u = new URL(String(value ?? '')); } catch { return { onHost: false, keyed: false }; }
  const parts = u.pathname.split('/');
  const onHost = u.origin === 'https://storage.cre.chain.link';
  const keyed = onHost && parts.length === 4 && parts[1] === 'artifacts'
    && parts[2].toLowerCase() === idBare && parts[3] === expectedLeaf;
  return { onHost, keyed };
}

function cdExplainUpsert(a) {
  const [name, tag, id, status, don, binUrl, cfgUrl, attrs, keepAlive] = a;
  const idBare = (id || '').replace(/^0x/, '').toLowerCase();
  const rows = [];

  // One name is expected here and everything else is a stop, the retired per-lane names included: this
  // system runs ONE registration now, so re-registering a lane-specific one is a mistake, not a variant.
  rows.push(cdRow('workflowName', name, name === CRE_WORKFLOW_NAME ? 'ok' : 'crit',
    name === CRE_WORKFLOW_NAME ? 'the consolidated four-lane workflow'
      : 'not the name this repo registers'));

  rows.push(cdRow('tag', tag, tag === name ? 'ok' : 'crit',
    tag === name ? 'matches the name, as the CLI registers it'
      : 'the record key is keccak(owner, name, tag) — a different tag creates a SEPARATE record'));

  const known = cdKnownWorkflow(id);
  rows.push(cdRow('workflowId', short(id), known ? 'crit' : 'ok',
    known ? `already registered as ${esc(known.t[WF.name])} — upsertWorkflow reverts WorkflowIDAlreadyExists on a re-used id`
      : 'hash of binary + config + owner + name. The binary is not reproducible, so this identifies the artifact rather than proving it'));

  // ACTIVE is a legitimate choice, not a defect, so it is described rather than flagged: registering
  // ahead of the author cutover costs rejected reports, and whether that is worth avoiding is the
  // operator's call, made once — not a warning re-raised on every paste.
  rows.push(cdRow('status', status === 0n ? '0 · ACTIVE' : status === 1n ? '1 · PAUSED' : String(status),
    status === 0n || status === 1n ? 'ok' : 'crit',
    status === 0n ? 'runs immediately. Until each lane\'s expectedAuthor points here, every tick is rejected (credits spent, no log)'
      : status === 1n ? 'registered but not running — reversible with activateWorkflow'
      : 'not a status this registry defines'));

  rows.push(cdRow('donFamily', don, don === DON_FAMILY ? 'ok' : 'crit',
    don === DON_FAMILY ? 'the family this owner holds quota on'
      : `expected ${DON_FAMILY} — and the registry refuses to change a family on update, so this is not fixable in place`));

  [['binaryUrl', binUrl, 'binary.wasm'], ['configUrl', cfgUrl, 'config']].forEach(([k, url, leaf]) => {
    const { onHost, keyed } = cdArtifactUrlStatus(url, idBare, leaf);
    rows.push(cdRow(k, url ? String(url).slice(0, 46) + (String(url).length > 46 ? '…' : '') : '(empty)',
      keyed ? 'ok' : 'crit',
      keyed ? `exact /artifacts/<workflowId>/${leaf} path on the CRE host — one build`
        : onHost ? `expected /artifacts/<workflowId>/${leaf} — URL path and artifact disagree`
        : 'not on storage.cre.chain.link — the DON would not load this'));
  });

  // The field this whole card exists for: attributes is the only place the deployed parameters can be
  // observed at all, because the artifact URLs above are 403 to everyone but the DON.
  const attrHex = String(attrs ?? '0x');
  const parsedAttrs = parseAttributes(attrHex);
  cdAttest = parsedAttrs.kind === 'attest' ? parsedAttrs.a : null;
  const repoParsed = (() => { try { return JSON.parse(CRE_CONFIG_JSON); } catch { return null; } })();
  let params = null, attrLevel, attrNote;
  if (parsedAttrs.kind === 'empty') {
    attrLevel = 'warn';
    attrNote = 'EMPTY — nothing about the deployed config or source would be observable. Re-emit with `just cre-attach-params` first';
  } else if (parsedAttrs.kind === 'attest') {
    // Two digests, each checked against a file this page can hash. The row reports the weaker of the two
    // checks; the artifact table below gives the per-file verdicts.
    const a = parsedAttrs.a;
    const cfgOk = a.config === creConfigSha;
    const srcOk = a.source === CRE_SOURCE_SHA256;
    attrLevel = !cfgOk || !srcOk ? 'crit' : 'ok';
    attrNote = !cfgOk ? 'attested config digest is NOT this repo\'s — different parameters would be deployed'
      : !srcOk ? 'attested source digest is NOT this repo\'s main.ts — that is different code'
      : 'both digests match this repo — re-hash either file below to confirm';
  } else if (parsedAttrs.kind === 'config') {
    params = parsedAttrs.config;
    const agree = paramsAgreement(attrHex, params, CRE_CONFIG_JSON, repoParsed);
    attrLevel = agree.level;
    attrNote = agree.level === 'ok' ? `${agree.note} (the older verbatim-config payload)`
      : `${agree.note} — the lanes below are what this payload would actually publish`;
  } else if (parsedAttrs.kind === 'attest-unknown') {
    attrLevel = 'crit';
    attrNote = `attestation version ${esc(String(parsedAttrs.a.v))} — this page checks cre-attest/3 and cannot verify this payload`;
  } else {
    attrLevel = 'crit';
    attrNote = 'neither a cre-attest payload nor a workflow config — do not sign metadata nobody can read';
  }
  rows.push(cdRow('attributes', `${parsedAttrs.bytes} bytes`, attrLevel, attrNote));
  if (parsedAttrs.kind === 'attest') {
    const a = parsedAttrs.a;
    rows.push(cdRow('· attested config', short('0x' + String(a.config ?? '')), a.config === creConfigSha ? 'ok' : 'crit',
      a.config === creConfigSha ? 'sha256(config.deploy.json) — also an input to the workflowId above' : 'does not match this repo'));
    rows.push(cdRow('· attested source', short('0x' + String(a.source ?? '')), a.source === CRE_SOURCE_SHA256 ? 'ok' : 'crit',
      a.source === CRE_SOURCE_SHA256 ? 'sha256(main.ts) — one file, so this covers the whole workflow' : 'does not match this repo\'s main.ts'));
    // Neutral by design: this row states the limit of the check, it is not a finding about THIS payload.
    // Given a verdict level it would raise the headline on every clean paste and train the reader to
    // scroll past the banner.
    rows.push(cdRow('· what a match proves', 'declaration only', '',
      'The owner writes these digests, and the uploaded artifacts are 403 to everyone but the DON. A match shows the config and source here are the ones DECLARED at registration — not that the DON executes them.'));
  }

  rows.push(cdRow('keepAlive', String(keepAlive), keepAlive === false ? 'ok' : 'warn',
    keepAlive === false ? 'an earlier record under this owner+name is paused as this one registers — replace-in-place'
      : 'earlier records stay ACTIVE — two workflows would run the same job'));

  // The crons and the networks are the substance of this registration, and they are in the calldata ONLY
  // when attributes carries the config. When it does not, say where they went rather than rendering an
  // empty table: "no triggers shown" and "no triggers registered" are opposite claims.
  // The bytes themselves, decoded. A reader checking a signature should see the exact text that would
  // land on-chain — 172 characters of UTF-8 JSON — not only this page's verdict about it. Escaped, and
  // shown for anything that decoded as text, including a payload this page does not recognise.
  const attrsBlock = parsedAttrs.text
    ? `<div class="cdsum">attributes, decoded (UTF-8 JSON, ${parsedAttrs.bytes} bytes):
         <div class="cdjson mono">${esc(parsedAttrs.text)}</div></div>`
    : parsedAttrs.kind === 'binary'
      ? `<div class="cdsum">attributes: ${parsedAttrs.bytes} bytes that are not valid UTF-8 — nothing to display as text.</div>`
      : '';

  let extra;
  if (!params && parsedAttrs.kind === 'attest' && parsedAttrs.a.config === creConfigSha) {
    // The payload carries a digest, not the bytes — but it is the digest of the copy this page holds,
    // so the triggers can be shown, sourced honestly: "the config this attests to", not "the chain's".
    params = repoParsed;
  }
  if (params) {
    const laneTab = laneTableHtml(params.lanes);
    if (laneTab.issues.length) {
      rows.push(cdRow('lane triggers', `${(params.lanes ?? []).length} trigger${(params.lanes ?? []).length === 1 ? '' : 's'}`,
        worst(laneTab.issues.map(i => i.level)), laneTab.issues.map(i => i.text).join(' · ')));
    } else {
      rows.push(cdRow('lane triggers', `${(params.lanes ?? []).length} triggers`, 'ok',
        'one cron per network, four lanes, staggered'));
    }
    extra = attrsBlock + `<div class="cdsum">Triggers this payload registers — ${parsedAttrs.kind === 'attest'
      ? 'from this repo\'s config.deploy.json, whose digest the payload attests' : 'decoded from the payload itself'} · receiver
      <span class="mono">${esc(short(params.receiverAddress))}</span> · target
      <span class="mono">${esc(short(params.targetAddress))}</span> · write gas limit
      <span class="mono">${esc(String(params.writeGasLimit ?? '—'))}</span></div>${laneTab.html}`;
  } else {
    extra = attrsBlock + `<div class="cdsum">⚠ <strong>The crons and networks are not in this calldata.</strong> They live in the 403-gated
      config artifact, so what this would schedule cannot be read from the bytes you are signing. Re-emit with
      <span class="mono">just cre-attach-params</span> and paste it here again.</div>`;
  }

  return { title: `upsertWorkflow — register or replace <strong>${esc(String(name))}</strong>`, rows, extra };
}

function cdExplain(sel, fn, args) {
  if (sel === '0xb377bfc5') return cdExplainUpsert(args);
  const rows = [];
  const named = id => { const k = cdKnownWorkflow(id); return k ? esc(k.t[WF.name]) : 'not among the records this tab read'; };
  if (fn.name === 'pauseWorkflow' || fn.name === 'deleteWorkflow') {
    rows.push(cdRow('workflowId', short(args[0]), cdKnownWorkflow(args[0]) ? 'ok' : 'warn', named(args[0])));
    rows.push(cdRow('effect', fn.name, fn.name === 'deleteWorkflow' ? 'crit' : 'ok',
      fn.name === 'deleteWorkflow' ? 'IRREVERSIBLE — re-registering needs a fresh artifact, since a re-used workflowId is rejected'
        : 'stops execution, frees the ACTIVE slot; reversible with activateWorkflow',
      false, fn.name === 'deleteWorkflow'));
  } else if (fn.name === 'activateWorkflow') {
    rows.push(cdRow('workflowId', short(args[0]), cdKnownWorkflow(args[0]) ? 'ok' : 'warn', named(args[0])));
    rows.push(cdRow('donFamily', args[1], args[1] === DON_FAMILY ? 'ok' : 'crit',
      args[1] === DON_FAMILY ? 're-checks the ACTIVE quota on this family' : `expected ${DON_FAMILY}`));
  } else if (fn.name === 'batchPauseWorkflows') {
    (args[0] || []).forEach((id, i) => rows.push(cdRow(`workflowIds[${i}]`, short(id), cdKnownWorkflow(id) ? 'ok' : 'warn', named(id))));
  } else if (fn.name === 'updateWorkflowDONFamily') {
    rows.push(cdRow('workflowId', short(args[0]), cdKnownWorkflow(args[0]) ? 'ok' : 'warn', named(args[0])));
    rows.push(cdRow('newDonFamily', args[1], args[1] === DON_FAMILY ? 'ok' : 'crit', 'moves it to another DON family — quota is per family'));
  } else if (fn.name === 'linkOwner') {
    rows.push(cdRow('validityTimestamp', new Date(Number(args[0]) * 1000).toLocaleString(),
      Number(args[0]) * 1000 > Date.now() ? 'ok' : 'crit',
      Number(args[0]) * 1000 > Date.now() ? 'the attestation is still valid' : 'EXPIRED — the registry would reject this'));
    rows.push(cdRow('proof', short(args[1]), 'ok', 'single-use — the registry never clears it, so a re-link needs a fresh backend-issued proof'));
    rows.push(cdRow('signature', `${(String(args[2]).length - 2) / 2} bytes`, 'ok',
      'Chainlink\'s attestation over the claimed owner — NOT the owner\'s own signature'));
    rows.push(cdRow('who gets linked', 'msg.sender', 'warn',
      'links WHOEVER SENDS IT — the wrong sender links the wrong address and spends the proof'));
  } else if (fn.name === 'unlinkOwner') {
    rows.push(cdRow('owner', `${holder(args[0])} <span class="mono">${short(args[0])}</span>`, 'crit',
      'DESTRUCTIVE — deletes every workflow this owner holds and burns the proof permanently', true, true));
  }
  return { title: `${fn.name} — ${REG_FN_PROSE[fn.name] ?? 'WorkflowRegistry call'}`, rows, extra: '' };
}
const REG_FN_PROSE = {
  pauseWorkflow: 'stop a registered workflow', activateWorkflow: 'resume a paused workflow',
  deleteWorkflow: 'erase a registration', batchPauseWorkflows: 'stop several workflows at once',
  updateWorkflowDONFamily: 'move a workflow to another DON family',
  linkOwner: 'admit an address as a workflow owner', unlinkOwner: 'remove an owner — and its workflows',
};

// Safe wrapper: the same bytes are often pasted as a whole execTransaction. Unwrap it, check the parts
// a signer cannot see (destination, value, and above all `operation`), then explain the inner call.
function cdExplainSafeExec(args) {
  const [to, value, data, operation, safeTxGas, baseGas, gasPrice, gasToken, refundReceiver, signatures] = args;
  const noGasToken = String(gasToken).toLowerCase() === ZERO.toLowerCase();
  const noRefundReceiver = String(refundReceiver).toLowerCase() === ZERO.toLowerCase();
  const signatureBytes = Math.max(0, (String(signatures).length - 2) / 2);
  const rows = [
    cdRow('to', `${holder(to)} <span class="mono">${short(to)}</span>`,
      (to || '').toLowerCase() === L1.workflowRegistry.toLowerCase() ? 'ok' : 'crit',
      (to || '').toLowerCase() === L1.workflowRegistry.toLowerCase() ? 'the L1 WorkflowRegistry this dashboard tracks'
        : `NOT the WorkflowRegistry (${short(L1.workflowRegistry)}) — this calldata does not mean here what it says`, true),
    cdRow('value', `${value} wei`, value === 0n ? 'ok' : 'crit', value === 0n ? 'no ETH moves' : 'this call also sends ETH'),
    cdRow('operation', operation === 0n ? '0 · CALL' : operation === 1n ? '1 · DELEGATECALL' : `${operation} · INVALID`, operation === 0n ? 'ok' : 'crit',
      operation === 0n ? 'an ordinary call' : 'only CALL is expected for a registry transaction'),
    cdRow('safeTxGas', String(safeTxGas), '', 'execution gas cap — the Safe estimates this; this page has no pinned value'),
    cdRow('baseGas', String(baseGas), baseGas === 0n ? 'ok' : 'crit',
      baseGas === 0n ? 'no base-gas reimbursement' : 'nonzero reimbursement input — not expected for this transaction'),
    cdRow('gasPrice', String(gasPrice), gasPrice === 0n ? 'ok' : 'crit',
      gasPrice === 0n ? 'refund disabled' : 'the Safe may reimburse the executor — not expected here'),
    cdRow('gasToken', `${holder(gasToken)} ${short(gasToken)}`, noGasToken ? 'ok' : 'crit',
      noGasToken ? 'native token sentinel; inert while gasPrice is zero' : 'token reimbursement setting — not expected here', true),
    cdRow('refundReceiver', `${holder(refundReceiver)} ${short(refundReceiver)}`, noRefundReceiver ? 'ok' : 'crit',
      noRefundReceiver ? 'default refund receiver; inert while gasPrice is zero' : 'attacker-chosen refund receiver — not expected here', true),
    cdRow('signatures', `${signatureBytes} bytes`, '',
      'ABI-valid bytes only — the Safe verifies signer ownership and threshold on-chain'),
  ];
  return { rows, inner: data };
}

let cdLast = '';
// The attestation currently in view: the pasted calldata's if there is one, otherwise the registered
// record's. Kept apart so a paste cannot silently overwrite what the chain says, and vice versa.
let cdAttest = null, regAttest = null;
// Files the reader dropped in, by role, with the digest computed here.
const cdFiles = { source: null, config: null };

const CD_ROLES = [
  { key: 'config', label: 'config.deploy.json', field: 'config', pin: () => CRE_CONFIG_SHA256,
    worth: 'the deployed parameters' },
  { key: 'source', label: 'main.ts', field: 'source', pin: () => CRE_SOURCE_SHA256,
    worth: 'the whole workflow, one file' },
];

function renderArtifactChecks() {
  const out = document.getElementById('cd-files-out');
  const a = cdAttest ?? regAttest;
  const src = cdAttest ? 'the pasted calldata' : regAttest ? 'the registered record' : null;
  const rows = CD_ROLES.map(r => {
    const got = cdFiles[r.key];
    const want = a ? String(a[r.field] ?? '') : r.pin();
    const wantFrom = a ? `attested by ${src}` : r.pin() ? 'pinned in this page' : null;
    let verdict, note;
    if (!got) {
      verdict = ''; note = want ? `expected <span class="mono">${esc(want.slice(0, 16))}…</span> · ${wantFrom}` : 'nothing to compare against';
    } else if (!want) {
      verdict = 'warn'; note = 'no attestation and no pin to compare against';
    } else if (got.sha === want) {
      verdict = 'ok'; note = `matches · ${wantFrom}`;
    } else {
      verdict = 'crit'; note = `expected <span class="mono">${esc(want.slice(0, 16))}…</span> · ${wantFrom}`;
    }
    return `<tr>
      <td class="rowlabel">${r.label}<span class="sub">${r.worth}</span></td>
      <td><span class="mono">${got ? got.sha.slice(0, 16) + '…' : '—'}</span></td>
      <td>${verdict ? chip(verdict, verdict === 'ok' ? 'match' : verdict === 'warn' ? 'no reference' : 'MISMATCH') : chip('', 'not supplied')}</td>
      <td class="s">${note}</td>
    </tr>`;
  }).join('');
  const header = a
    ? `<div class="cdsum">Reference: <strong>${src}</strong> · <span class="mono">${esc(String(a.v ?? ''))}</span></div>`
    : `<div class="cdsum">Reference: this page's own pins — no attestation in view.</div>`;
  out.innerHTML = header + `<div class="scroll-x"><table class="syncm">
    <tr><th>Artifact</th><th>sha256 of your file</th><th></th><th>Verdict</th></tr>${rows}</table></div>`;
}

async function cdTakeFile(key, file) {
  // The label next to the button is ours as well — the native control's "no file chosen" is drawn by the
  // browser in the browser's language, so nothing here reads it or relies on it.
  const nameEl = document.getElementById(key === 'source' ? 'cd-f-src-name' : 'cd-f-cfg-name');
  if (!file) {
    cdFiles[key] = null;
    if (nameEl) nameEl.textContent = 'no file selected';
    renderArtifactChecks();
    return;
  }
  const buf = new Uint8Array(await file.arrayBuffer());
  cdFiles[key] = { name: file.name, size: buf.length, sha: sha256Hex(buf) };
  if (nameEl) nameEl.textContent = `${file.name} · ${buf.length.toLocaleString()} bytes`;
  renderArtifactChecks();
}
function cdRenderRows(title, rows, extra) {
  const body = rows.map(r => `<tr>
    <td class="rowlabel">${esc(r.field)}</td>
    <td><span class="mono">${r.html ? r.value : esc(String(r.value))}</span></td>
    <td>${chip(r.level, r.level === 'ok' ? 'ok' : r.level === 'warn' ? 'check this' : r.level === 'crit' ? 'stop' : 'note')}</td>
    <td class="s">${r.note}</td>
  </tr>`).join('');
  return `<div class="cdsum">${title}</div>
    <div class="scroll-x"><table class="syncm">
      <tr><th>Field</th><th>Value</th><th></th><th>What it means here</th></tr>${body}</table></div>${extra ?? ''}`;
}

function decodeCalldataInput() {
  const out = document.getElementById('cd-out');
  cdAttest = null;
  renderArtifactChecks();
  const raw = (document.getElementById('cd-in').value || '').replace(/[\s"',]/g, '');
  cdLast = raw;
  if (!raw) { out.innerHTML = ''; return; }
  if (!/^0x[0-9a-fA-F]*$/.test(raw) || raw.length < 10) {
    out.innerHTML = `<div class="err-banner">✕ not calldata: expected 0x followed by at least a 4-byte selector</div>`;
    return;
  }
  let html = '', body = raw.slice(10), sel = raw.slice(0, 10).toLowerCase();
  const verdicts = [];
  let wrapRows = null;
  if (sel === SAFE_EXEC_SEL) {
    const args = decodeAbiArgs(body, SAFE_EXEC.types);
    if (!args) { out.innerHTML = `<div class="err-banner">✕ execTransaction selector, but the arguments do not decode</div>`; return; }
    const wrap = cdExplainSafeExec(args);
    wrapRows = wrap.rows;
    verdicts.push(...wrap.rows.map(r => r.level));
    html += cdRenderRows('Safe <strong>execTransaction</strong> — the outer envelope', wrap.rows, '');
    const inner = String(wrap.inner ?? '0x');
    if (inner.length < 10) { out.innerHTML = html + `<div class="err-banner">⚠ the inner call is empty</div>`; return; }
    sel = inner.slice(0, 10).toLowerCase(); body = inner.slice(10);
  }
  const fn = REG_FN[sel];
  if (!fn) {
    out.innerHTML = html + `<div class="err-banner">✕ unknown selector <span class="mono">${esc(sel)}</span> — not a WorkflowRegistry function this page knows.
      Do not sign it on the strength of a dashboard that could not read it.</div>`;
    return;
  }
  const args = decodeAbiArgs(body, fn.types);
  if (!args) {
    out.innerHTML = html + `<div class="err-banner">✕ selector says <span class="mono">${esc(fn.name)}</span>, but its arguments do not decode — malformed or truncated calldata</div>`;
    return;
  }
  const ex = cdExplain(sel, fn, args);
  verdicts.push(...ex.rows.map(r => r.level));
  // The headline is the WEAKEST field, stated first. A signer reading top-to-bottom must not have to
  // reach row nine to discover that row nine says stop.
  const critRows = [...(wrapRows ?? []), ...ex.rows].filter(r => r.level === 'crit');
  const crits = critRows.length, warns = verdicts.filter(v => v === 'warn').length;
  const byDesign = crits > 0 && critRows.every(r => r.destructive);
  html = (byDesign ? `<div class="err-banner">✕ irreversible by design — sign only if this is exactly the action you intend</div>`
    : crits ? `<div class="err-banner">✕ ${crits} field${crits > 1 ? 's' : ''} say${crits > 1 ? '' : 's'} STOP — do not sign this as it stands</div>`
    : warns ? `<div class="err-banner">⚠ ${warns} field${warns > 1 ? 's' : ''} to confirm deliberately — read the notes before signing</div>`
    : `<div class="cdsum">✓ No checked field conflicts with this page's pins. Where you send it from is still yours to check.</div>`) + html;
  html += cdRenderRows(ex.title, ex.rows, ex.extra);
  html += `<div class="cdsum">Send to <strong>${holder(L1.workflowRegistry)}</strong> <span class="mono">${short(L1.workflowRegistry)}</span> on Ethereum mainnet, from the linked owner. This page checked the calldata, not where you send it.</div>`;
  out.innerHTML = html;
  renderArtifactChecks();
}
// ── Page loop ────────────────────────────────────────────────────────────────
async function readCoreState() {
  const [l1, ...lanes] = await Promise.all([
    l1Data().then(d => ({ d })).catch(e => ({ error: e.message })),
    ...LANES.map(L => laneData(L).then(d => ({ L, d })).catch(e => ({ L, error: e.message }))),
  ]);
  return { l1, lanes };
}
async function refreshOverviewAccess() {
  const { l1, lanes } = await readCoreState();
  render(l1, lanes);
  return lanes;
}
async function refreshAutomationState(lanes) {
  const currentLanes = lanes ?? await Promise.all(LANES.map(L => laneData(L)
    .then(d => ({ L, d })).catch(e => ({ L, error: e.message }))));
  // The owner set is discovered, not hardcoded: whichever address each lane currently expects as its
  // report author is the one whose registry account matters. Survives the pending Safe migration.
  // CRE_WF_OWNER is included EXPLICITLY, not discovered: it owns the consolidated registration before
  // any lane's expectedAuthor points at it, so a purely discovered owner set would be blind to the new
  // workflow for exactly as long as the migration is mid-flight — the window that most needs watching.
  const owners = [...new Set([AUTO_OWNER, CRE_WF_OWNER,
    ...currentLanes.filter(l => !l.error && l.d.creAuthor).map(l => l.d.creAuthor.toLowerCase())])];
  let regs = null, regError = null;
  try { regs = await registryData(owners); } catch (e) { regError = e.message; }
  // Published together: a render that pairs this cycle's lanes with the previous cycle's registry would
  // show a just-changed expectedAuthor as an unlinked author and flash a false gate failure.
  automation.lanes = currentLanes;
  automation.regs = regs;
  automation.regError = regError;
  renderAutomation();
  // Verdicts like "this workflowId is already registered" need `regs`; a paste made while the first
  // read was still in flight would otherwise keep its weaker answer until the next keystroke.
  if (cdLast) decodeCalldataInput(); else renderArtifactChecks();
}
async function refreshAutomationLogs() {
  const results = await Promise.all(LANES.map(L => automationLogs(L)
    .then(events => { automation.logs[L.name] = events; return { L }; })
    .catch(e => ({ L, error: e.message }))));
  saveAutomationCache();
  automation.logErrors = results.filter(r => r.error).map(r => `${r.L.name} (${r.error})`);
  renderAutomation();
}
async function refreshActivity() {
  const results = await Promise.all(LANES.map(L => activityData(L)
    .then(events => { activityCache[L.name] = events; return { L, events }; })
    .catch(e => ({ L, error: e.message, events: activityCache[L.name] }))));
  saveActivityCache();
  activityRenderedAt = Date.now();
  renderActivity(results);
}
async function refreshSyncVolume() {
  syncVolumeRefreshing = true;
  updateSyncVolumeTile();
  const results = await Promise.all(LANES.map(L => syncVolumeData(L)
    .then(summary => ({ L, summary }))
    .catch(() => { const saved = readSyncProgress(L); return { L, cached: true,
      summary: { wei: BigInt(saved.wei), count: saved.count } }; })));
  const readable = results.filter(r => r.summary);
  syncVolume = { readable: readable.length, cached: results.some(r => r.cached),
    wei: readable.reduce((sum, r) => sum + r.summary.wei, 0n),
    count: readable.reduce((sum, r) => sum + r.summary.count, 0) };
  syncVolumeRefreshing = false;
  updateSyncVolumeTile();
}
let refreshAllPromise = null;
async function refreshAll() {
  if (refreshAllPromise) return refreshAllPromise;
  refreshAllPromise = (async () => {
    const core = refreshOverviewAccess();
    await Promise.all([
      core.then(lanes => refreshAutomationState(lanes)),
      refreshActivity(),
      refreshShuttles(),
      refreshSyncVolume(),
      refreshAutomationLogs(),
    ]);
  })();
  updateActivityUpd();
  try {
    await refreshAllPromise;
  } finally {
    refreshAllPromise = null;
    updateActivityUpd();
  }
}

async function refreshView(view) {
  const affected = view === 'main' || view === 'access' ? ['main', 'access'] : [view];
  if (affected.some(name => refreshingViews.has(name))) return;
  affected.forEach(name => { refreshingViews.add(name); updateViewRefresh(name); });
  try {
    if (refreshAllPromise) await refreshAllPromise;
    else if (view === 'activity') await refreshActivity();
    else if (view === 'shuttle') await refreshShuttles();
    else if (view === 'automation') await Promise.all([refreshAutomationState(), refreshAutomationLogs()]);
    else if (view === 'main') await Promise.all([refreshOverviewAccess(), refreshSyncVolume()]);
    else await refreshOverviewAccess();
  } finally {
    affected.forEach(name => { refreshingViews.delete(name); updateViewRefresh(name); });
  }
}

const tabButtons = [...document.querySelectorAll('.tab')];
let activeTab = 'main';

function setTabStatus(tab, status) {
  const button = tabButtons.find(b => b.dataset.tab === tab);
  if (!button) return;
  button.dataset.status = status ?? '';
  button.title = status === 'crit' ? 'Critical issue' : status === 'warn' ? 'Warning' : status === 'new' ? 'New activity' : '';
}

function selectTab(tab) {
  const selected = tabButtons.find(b => b.dataset.tab === tab) ?? tabButtons[0];
  activeTab = selected.dataset.tab;
  tabButtons.forEach(b => b.classList.toggle('active', b === selected));
  tabButtons.forEach(b => document.getElementById(b.dataset.tab).hidden = b !== selected);
  if (activeTab === 'activity') {
    activityViewBoundary = activitySeen;   // highlight what arrived since the last visit
    markActivitySeen();
    if (lastActivityResults) renderActivity(lastActivityResults);
  }
  if (location.hash !== '#' + activeTab) history.replaceState(null, '', '#' + activeTab);
}

tabButtons.forEach(b => b.onclick = () => selectTab(b.dataset.tab));
window.addEventListener('hashchange', () => selectTab(location.hash.slice(1)));
document.addEventListener('click', event => {
  const button = event.target.closest('[data-refresh-view]');
  if (button) refreshView(button.dataset.refreshView);
});
selectTab(location.hash.slice(1));

// Decode as you type: the check is pure local parsing, and a signer who has to press a button to learn
// what a blob does will read the blob instead.
document.getElementById('cd-go').onclick = decodeCalldataInput;
document.getElementById('cd-in').addEventListener('input', decodeCalldataInput);
document.getElementById('cd-clear').onclick = () => {
  document.getElementById('cd-in').value = '';
  decodeCalldataInput();
};
[['source', 'cd-f-src'], ['config', 'cd-f-cfg']].forEach(([key, id]) =>
  document.getElementById(id).addEventListener('change', e => cdTakeFile(key, e.target.files?.[0])));
// Pasting the source is the same check by another route — for a reviewer reading a diff in a browser
// rather than holding the file. Byte-exact or it will not match, which is the point.
document.getElementById('cd-src-paste').addEventListener('input', e => {
  const text = e.target.value;
  cdFiles.source = text ? { name: 'pasted text', size: new TextEncoder().encode(text).length, sha: sha256Hex(text) } : null;
  renderArtifactChecks();
});
renderArtifactChecks();

document.getElementById('rpcbtn').onclick = openRpcDialog;
document.getElementById('rpcsave').onclick = saveRpcDialog;
document.getElementById('rpccancel').onclick = () => document.getElementById('rpcdlg').close();
document.getElementById('rpcreset').onclick = () => {
  document.querySelectorAll('#rpcrows .row').forEach(row => {
    row.querySelector('input').value = '';
    row.querySelector('input').classList.remove('bad');
    row.querySelector('.msg').className = 'msg dim';
    row.querySelector('.msg').textContent = 'using the built-in public endpoint';
  });
};
// Per-row "Default" clears the field; saving with it empty is what actually drops the override.
document.getElementById('rpcrows').addEventListener('click', e => {
  if (!e.target.classList.contains('clear')) return;
  const row = e.target.closest('.row');
  row.querySelector('input').value = '';
  row.querySelector('input').classList.remove('bad');
  row.querySelector('.msg').className = 'msg dim';
  row.querySelector('.msg').textContent = 'using the built-in public endpoint';
});
applyRpcOverrides(); // before the first read, so a stored override is used from the very first paint
if (LANES.some(L => activityCache[L.name]))
  renderActivity(LANES.map(L => ({ L, events: activityCache[L.name] })));
refreshAll();
setInterval(refreshAll, 60_000);
